/* ---------- helpers ---------- */
const lockPanel=(title,why,key)=>`<section class="panel lock-panel"><div class="lock-icon">${ic('lock')}</div><h2>${title}</h2><p>${why}</p><p class="small muted">Yetki = organizasyon üyeliği + rol izni + kaynak ataması + veri sınıfı. Owner/admin rolü bu veriyi otomatik görmez (spec §4.4, §6). Hassas erişim step-up MFA + audit ile.</p><div class="actions">${key?btn('Break-glass erişim talebi','breakglass-request','','shield',`data-id="${key}"`):''}${btn('Rolü değiştir','switch-role','','user')}</div></section>`;
const docBadge=s=>badge(s,['Mevcut','İmzalandı'].includes(s)?'success':['Eksik','Süresi doldu','Reddedildi'].includes(s)?'danger':'warn');
const docsOf=id=>state.hrDocs.filter(d=>d.employee_id===id&&!d.deleted_at);
const completion=id=>{const ds=docsOf(id).filter(d=>d.category!=='Bordro / ödeme belgesi');const ok=ds.filter(d=>['Mevcut','İmzalandı'].includes(d.status)).length;return ds.length?Math.round(ok/ds.length*100):0};
const expiring=(days=60)=>state.hrDocs.filter(d=>d.expires_at&&!d.deleted_at&&daysFromToday(d.expires_at)<=days);
const activeEmps=()=>state.employees.filter(e=>['Aktif','Ayrılıyor'].includes(e.status));
const myTeam=()=>state.employees.filter(e=>e.manager===account().person||e.id===account().person);
const canArchive=()=>grant('can.read.hr.archive');
const selfId=()=>account().person;
const isSelf=id=>id===selfId();
const uiTabs=(key,items,cur)=>`<div class="tabs" role="tablist">${items.map(([id,l])=>`<button class="tab ${cur===id?'active':''}" role="tab" aria-selected="${cur===id}" data-action="ui" data-key="${key}" data-value="${id}">${l}</button>`).join('')}</div>`;
const empSel=()=>`<label class="form-field" style="min-width:240px">Çalışan<select data-ui-sel="emp" aria-label="Çalışan seç">${state.employees.map(e=>option(e.id,`${e.name} · ${e.status}`,curEmp().id)).join('')}</select></label>`;
const curEmp=()=>emp(ui.emp)||(role()==='creative'||role()==='manager'?emp(selfId()):null)||state.employees[0];
function peopleNav(){const r=role();const allowed=peopleAllowed();return `<div class="subnav people-nav" role="tablist" aria-label="JS People bölümleri">${PEOPLE_GROUPS.map(([g,ids])=>`<span class="subnav-label">${g}</span>${ids.map(id=>{const t=subTabs.people.find(x=>x[0]===id);const off=!allowed.includes(id);return `<button role="tab" class="${sub===id?'active':''} ${off?'locked':''}" aria-selected="${sub===id}" data-action="sub" data-id="${id}" title="${off?'Bu rolde kilitli':''}"><span class="lbl">${t[1].replace(/ \[özel yetki\]/,'')}${off?' '+ic('lock'):''}</span></button>`}).join('')}`).join('')}</div>`}
function peopleAllowed(){const r=role();const all=subTabs.people.map(t=>t[0]);if(r==='manager')return ['genel','izin','c360'];if(r==='payroll')return ['genel','calisanlar','c360','bordro','ucret','mesai','raporlar','kolayik'];if(r==='owner')return all.filter(x=>!['bordro','ucret'].includes(x));if(r==='hr')return all.filter(x=>!['bordro','ucret'].includes(x));return ['genel','c360','izin'];}
function people(){const parts={genel:peopleOverview,calisanlar:peopleDirectory,c360:people360,'arsiv-aktif':arcActive,'arsiv-eski':arcFormer,'arsiv-turler':arcTypes,'arsiv-eksik':arcMissing,'arsiv-toplu':arcBulk,'arsiv-saklama':arcRetention,'arsiv-erisim':arcAccess,izin:peopleLeaveCenter,mesai:peopleAttendance,masraf:peopleExpenses,zimmet:peopleAssetsReg,egitim:peopleTraining,performans:peoplePerf,ucret:peopleComp,bordro:peoplePayroll,onboarding:peopleOnOff,raporlar:peopleReports,kolayik:peopleMigration};const lock={bordro:['Bordro ve ödeme belgeleri ayrı yetkidir','Bu rolde Payroll Vault görünmez. Bordro yöneticisi (Payroll) rolü + step-up MFA gerekir.','can.read.payroll'],ucret:['Ücret / prim geçmişi ayrı yetkidir','Ücret verisi; Payroll/Compensation yetkisi ve step-up MFA ister. Owner otomatik görmez.','can.read.compensation'],performans:['Performans kayıtları özel yetkidir','Yalnızca İK, ilgili yönetici ve çalışanın kendisi görür.','can.view.performance']};const allowed=peopleAllowed();const body=!allowed.includes(sub)?lockPanel(...(lock[sub]||['Bu bölüm bu rolde kilitli','Ekip yöneticisi yalnız kendi ekibinin izin takvimini ve özetleri görür; çalışan kendi kartını görür.','can.read.hr.archive'])):(parts[sub]||peopleOverview)();const act=role()==='hr'||role()==='owner'?btn('Personel ekle','emp-new','primary','plus')+btn('İzin talebi','leave-new','','plus'):btn('İzin talebi','leave-new','primary','plus');return head('İNSAN & MÜŞTERİ · JS PEOPLE',role()==='manager'?'Ekibim.':'İnsanlar önce.','HRIS: çalışan yaşam döngüsü, tam personel arşivi, izin/mesai, masraf/zimmet/eğitim, performans/ücret/bordro (ayrı yetki), HR raporları ve Kolay İK aktarım merkezi. İşe alım JS Hire’da kalır.',act)+`<div class="toolbar">${peopleNav()}</div>${body}`}

/* ---------- Genel Bakış ---------- */
function peopleOverview(){const mgr=role()==='manager';const list=mgr?myTeam():state.employees;const act=list.filter(e=>['Aktif','Ayrılıyor'].includes(e.status));const joins=list.filter(e=>e.start>='2026-10-01').length,exits=list.filter(e=>e.end&&e.end>='2026-10-01'&&e.end<='2026-10-31').length;const onLeave=state.leaves.filter(l=>l.status==='Onaylandı'&&l.from<='2026-10-31'&&l.to>='2026-10-12'&&list.some(e=>e.id===l.person));const miss=state.hrDocs.filter(d=>d.status==='Eksik'&&list.some(e=>e.id===d.employee_id)).length;const total=state.hrDocs.filter(d=>d.category!=='Bordro / ödeme belgesi'&&list.some(e=>e.id===d.employee_id)).length;const exp=expiring(60).filter(d=>list.some(e=>e.id===d.employee_id));const assets=state.hrAssets.filter(a=>a.status==='Zimmetli').length;const tr=state.trainingRecords.filter(t=>state.trainings.find(x=>x.id===t.training)?.mandatory);const trPct=tr.length?Math.round(tr.filter(t=>t.status==='Tamamlandı').length/tr.length*100):0;const pend=[...state.leaves.filter(l=>l.status==='Bekliyor').map(l=>[`İzin · ${empName(l.person)} · ${date(l.from)}–${date(l.to)} (${l.step} adımı)`,'people/izin']),...state.hrDocs.filter(d=>d.status==='HR onayı bekliyor').map(d=>[`Belge onayı · ${empName(d.employee_id)} · ${d.subcategory}`,'people/arsiv-eksik']),...state.expenseClaims.filter(x=>x.status==='Bekliyor').map(x=>[`Masraf · ${empName(x.emp)} · ${money(x.amount*x.rate)} (${x.step})`,'people/masraf']),...state.overtime.filter(o=>o.status==='Bekliyor').map(o=>[`Fazla mesai · ${empName(o.emp)} · ${o.hours} saat`,'people/mesai'])];const rem=[['29 Eki','Cumhuriyet Bayramı · resmî tatil'],['30 Eki','Berke A. son çalışma günü · offboarding'],['01 Kas','Raif Vural iş yıl dönümü (3 yıl)'],['05 Kas','Hulusi M. Özbay sağlık raporu yenileme'],['12 Kas','Selin Tekin son çalışma günü']];return `<section class="metrics">${metric('Çalışan',act.length,`${list.filter(e=>e.status==='Teyit bekliyor').length} teyit bekliyor · ${list.filter(e=>e.status==='Ayrıldı').length} eski`,'people')}${metric('Giriş / çıkış (Ekim)',`${joins} / ${exits}`,'işe giriş · planlı ayrılış','activity')}${metric('İzinde',onLeave.length,'bu ay onaylı izin','clock')}${metric('Eksik belge',`%${total?Math.round(miss/total*100):0}`,`${miss} belge · arşiv tutarlılığı`,'files')}${metric('Süresi dolacak',exp.length,'60 gün içinde · belge/sertifika','flag')}${metric('Zimmet',assets,'aktif zimmetli varlık','resources')}${metric('Eğitim tamamlanma',`%${trPct}`,'zorunlu eğitimler','star')}</section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Bekleyen İK işlemleri <span class="muted small">${pend.length}</span></h2></div><div class="panel-body"><ul class="meeting-list">${pend.map(([t,h])=>`<li>${ic('clock')}<a href="#${h}">${esc(t)}</a></li>`).join('')||'<li class="muted">Bekleyen işlem yok.</li>'}</ul></div></div><div class="panel"><div class="panel-header"><h2>Hatırlatmalar</h2>${badge('Takvim','neutral')}</div><div class="panel-body"><ul class="meeting-list">${rem.map(([d,t])=>`<li><strong class="mono">${d}</strong><span>${esc(t)}</span></li>`).join('')}</ul></div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Organizasyon şeması</h2><span class="small muted">yönetici hiyerarşisi · vekâlet</span></div><div class="panel-body"><div class="org-chart">${orgNode('BY')}</div></div></section>`}
function orgNode(id){const kids=state.employees.filter(e=>e.manager===id&&e.status!=='Ayrıldı');const me=emp(id)||{name:'Batuhan Berk Yaşar',title:'Kurucu'};return `<div class="org-node"><button class="org-card" data-action="e360-open" data-id="${id}"><strong>${esc(me.name)}</strong><small>${esc(me.title)}</small>${me.status==='Ayrılıyor'?badge('Ayrılıyor'):''}</button>${kids.length?`<div class="org-kids">${kids.map(k=>orgNode(k.id)).join('')}</div>`:''}</div>`}

/* ---------- Çalışanlar ---------- */
function peopleDirectory(){const list=state.employees.filter(e=>filter==='Tümü'||e.status===filter);return `<div class="toolbar">${tabs(['Tümü','Aktif','Ayrılıyor','Teyit bekliyor','Ayrıldı'])}<input class="search" data-search="emp-list" data-fn="empListRows" placeholder="Ad, unvan, ekip ara" aria-label="Çalışan ara"></div><div class="emp-grid" id="emp-list">${empListRows()}</div>`}
window.empListRows=function(){const q=(query||'').toLocaleLowerCase('tr');return state.employees.filter(e=>(filter==='Tümü'||e.status===filter)&&`${e.name} ${e.title} ${e.team}`.toLocaleLowerCase('tr').includes(q)).map(e=>`<article class="panel emp-card"><div class="card-top"><div class="avatar">${initials(e.name)}</div><div><h2>${esc(e.name)}</h2><small>${esc(e.title)} · ${esc(e.team)} · ${esc(e.workType)}</small></div>${badge(e.status)}</div>${kv([['Yönetici',esc(empName(e.manager))],['Başlangıç',date(e.start)+(e.end?' → '+date(e.end):'')],['Kıdem',`${kidem(e)} yıl · ${entitlement(e)} gün izin`],['Belge tamamlanma',meter(completion(e.id))+`<small>%${completion(e.id)}</small>`]])}<div class="actions">${btn('Çalışan 360','e360-open','sm primary','arrow',`data-id="${e.id}"`)}${e.status==='Teyit bekliyor'?btn('Statüyü teyit et','emp-confirm','sm','check',`data-id="${e.id}"`):''}</div></article>`).join('')||'<p class="empty">Eşleşen çalışan yok.</p>'};
const E360_TABS=[['profil','Profil & Organizasyon'],['ozluk','Özlük Belgeleri'],['sozlesme','İş Sözleşmeleri'],['izin','İzin & Devamsızlık'],['mesai','Mesai / Puantaj / Vardiya'],['bordro','Bordro & Ödeme [özel yetki]'],['ucret','Ücret / Prim [özel yetki]'],['zimmet','Zimmetler'],['egitim','Eğitim / Sertifikalar'],['performans','Performans [özel yetki]'],['dosya','İşe Giriş / Ayrılış Dosyası']];
function people360(){const e=curEmp();const t=ui.e360||'profil';const mgr=role()==='manager';if(mgr&&!myTeam().some(x=>x.id===e.id))return lockPanel('Yalnızca kendi ekibin','Ekip yöneticisi başka ekiplerin kartlarını görmez.','');const parts={profil:e360Profile,ozluk:e360Docs,sozlesme:e360Contracts,izin:e360Leave,mesai:e360Attendance,bordro:e360Payroll,ucret:e360Comp,zimmet:e360Assets,egitim:e360Training,performans:e360Perf,dosya:e360File};return `<div class="toolbar">${mgr?`<strong>${esc(e.name)}</strong>`:empSel()}${badge(e.status)}${badge(e.workType,'neutral')}${e.externalId?`<span class="chip">source: kolayik · ${esc(e.externalId)}</span>`:''}</div>${uiTabs('e360',E360_TABS,t)}${(parts[t]||e360Profile)(e)}`}
function e360Profile(e){const i=state.employees.indexOf(e);const hr=canArchive();const ed=(label,path,val)=>hr?`<label class="form-field">${label}<input data-bind="${path}" value="${esc(val)}"></label>`:`<label class="form-field">${label}<input value="${esc(val)}" readonly></label>`;return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Organizasyon</h2>${hr?badge('Düzenlenebilir · İK','neutral'):badge('Salt okunur','neutral')}</div><div class="panel-body"><div class="form-grid">${ed('Unvan',`employees.${i}.title`,e.title)}${ed('Departman / ekip',`employees.${i}.team`,e.team)}${ed('Şirket',`employees.${i}.company`,e.company||'Jobs Studio')}${ed('Lokasyon',`employees.${i}.location`,e.location||'')}${ed('Maliyet merkezi',`employees.${i}.costCenter`,e.costCenter||'')}<label class="form-field">Çalışma tipi${hr?sel(`employees.${i}.workType`,['Tam zamanlı','Part-time','Stajyer','Freelance'],e.workType):`<input value="${esc(e.workType)}" readonly>`}</label><label class="form-field">Yönetici${hr?`<select data-bind="employees.${i}.manager">${[['BY','Batuhan Berk Yaşar'],...state.employees.filter(x=>x.id!==e.id).map(x=>[x.id,x.name])].map(([v,l])=>option(v,l,e.manager)).join('')}</select>`:`<input value="${esc(empName(e.manager))}" readonly>`}</label><label class="form-field">Durum${hr?sel(`employees.${i}.status`,['Aktif','Ayrılıyor','Teyit bekliyor','Ayrıldı'],e.status,'data-rerender'):`<input value="${esc(e.status)}" readonly>`}</label><label class="form-field">İşe giriş<input type="date" value="${e.start}" readonly></label><label class="form-field">Ayrılış<input type="date" value="${e.end||''}" readonly></label></div></div></div><div class="panel"><div class="panel-header"><h2>İletişim & özlük</h2>${badge(hr||isSelf(e.id)?'Yetkili':'Maskeli','neutral')}</div><div class="panel-body">${kv([['E-posta',esc(e.email)],['Telefon',hr||isSelf(e.id)?'+90 5•• ••• •• ••':MASK_HR],['Adres',hr||isSelf(e.id)?'Ankara (detay gizli)':MASK_HR],['TC kimlik',MASK_HR],['IBAN',MASK],['Acil durum kişisi',hr||isSelf(e.id)?'Kayıtlı · 1 kişi':MASK_HR],['Özel alanlar','Zorunlu olmayan veri toplanmaz']])}<p class="small muted">Gerçek kimlik, adres ve banka verisi demoda tutulmaz; alan bazlı maskeleme + step-up doğrulama ilkesi.</p></div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Çalışma geçmişi</h2>${hr?btn('Kayıt ekle','hist-add','sm','plus',`data-id="${e.id}"`):''}</div><div class="panel-body"><div class="timeline">${(e.history||[]).map(h=>`<div class="timeline-entry"><strong>${date(h.at)}</strong> · ${badge(h.type,'neutral')} ${esc(h.text)}</div>`).join('')||'<p class="empty">Kayıt yok.</p>'}</div></div></section>`}
function docRow(d,o={}){const sens=d.confidentiality_level==='Özel nitelikli'||d.confidentiality_level==='Bordro';const canSee=o.canSee??(canArchive()||isSelf(d.employee_id));const i=state.hrDocs.indexOf(d);return `<tr class="${d.status==='Eksik'?'row-danger':''}"><td><strong>${esc(d.subcategory)}</strong><br><small class="muted mono">${esc(d.original_filename)} · v${d.version_number}${d.legal_hold_flag?' · LEGAL HOLD':''}</small></td><td>${esc(d.category)}</td><td>${badge(d.confidentiality_level,sens?'danger':'neutral')}</td><td>${date(d.document_date)}${d.expires_at?`<br><small class="${daysFromToday(d.expires_at)<0?'danger-text':daysFromToday(d.expires_at)<=60?'warn-text':'muted'}">son: ${date(d.expires_at)}</small>`:''}</td><td>${o.statusSel?`<select data-doc-status="${i}" aria-label="${esc(d.subcategory)} durumu">${DOC_STATUSES.map(s=>option(s,s,d.status)).join('')}</select>`:docBadge(d.status)}</td><td class="actions nowrap">${canSee?btn('Aç','doc-open','sm','eye',`data-id="${d.id}"`):badge('Yetki gerekir','danger')}${d.status==='Eksik'?btn('Yükleme talebi','doc-request','sm','upload',`data-id="${d.id}"`):''}${d.status==='HR onayı bekliyor'&&canArchive()?btn('Onayla','doc-approve','sm primary','check',`data-id="${d.id}"`):''}</td></tr>`}
const docTable=(docs,o={})=>tbl(['BELGE','KATEGORİ','GİZLİLİK','TARİH','DURUM',''],docs.map(d=>docRow(d,o)).join(''),'Belgeler');
function e360Docs(e){if(!(canArchive()||isSelf(e.id)))return lockPanel('Özlük arşivi ayrı yetkidir','Owner/admin otomatik tam erişim almaz. İK personel yöneticisi yetkili çalışanların arşivini görür; çalışan kendi belgelerini görür.','can.read.hr.archive');const docs=docsOf(e.id).filter(d=>['İşe giriş evrakı','Görev tanımı','İmzalı formlar','İzin evrakı','Zimmet tutanağı','Eğitim belgeleri'].includes(d.category));return `<div class="toolbar"><span class="small muted">Dijital dosya dolabı · ${docs.length} belge · tamamlanma %${completion(e.id)}</span>${canArchive()?btn('Belge yükle','doc-upload','sm','upload',`data-id="${e.id}"`):btn('Belge yükle (self-servis)','doc-upload','sm','upload',`data-id="${e.id}"`)}</div>${docTable(docs)}`}
function e360Contracts(e){if(!(canArchive()||isSelf(e.id)))return lockPanel('Sözleşmeler özlük arşivinin parçasıdır','İK yetkisi gerekir.','can.read.hr.archive');const docs=docsOf(e.id).filter(d=>['Sözleşme & ek protokol','İmzalı formlar'].includes(d.category));return `<div class="banner">${ic('info')}<span>Ekim 2026 imza seti: iş sözleşmesi, Ek-1 hibrit, Ek-2 el kitabı, KVKK aydınlatma, açık rıza, fazla çalışma, zimmet, gizlilik. Durum değişikliği işlem kaydına yazılır; e-imza entegrasyonu plan.</span></div>${docTable(docs,{statusSel:canArchive()})}`}
function e360Leave(e){const ls=state.leaves.filter(l=>l.person===e.id);const used=ls.filter(l=>l.status==='Onaylandı'&&l.type==='Yıllık izin').reduce((s,l)=>s+(l.days||1),0)+(e.leaveUsed||0);const tot=entitlement(e)+(e.leaveOpening||0);return `<section class="metrics">${metric('Hak ediş',`${entitlement(e)} <small>gün</small>`,`kıdem ${kidem(e)} yıl · Kolay İK kuralı`,'clock')}${metric('Açılış bakiyesi',`${e.leaveOpening||0}`,'önceki dönemden devir','activity')}${metric('Kullanılan',used,'onaylı yıllık izin','check')}${metric('Kalan',Math.max(0,tot-used),'gün','flag')}</section>${tbl(['TÜR','TARİH','GÜN','VEKİL','ADIM','DURUM',''],ls.map(l=>`<tr><td>${esc(l.type)}</td><td>${date(l.from)} – ${date(l.to)}</td><td>${l.days||1}</td><td>${l.deputy?esc(empName(l.deputy)):'—'}</td><td>${esc(l.step||'—')}</td><td>${badge(l.status)}</td><td>${l.status==='Bekliyor'&&isSelf(e.id)?btn('İptal','leave-cancel','sm','close',`data-id="${l.id}"`):''}</td></tr>`).join(''),'İzin geçmişi')}<div class="form-actions" style="justify-content:start">${btn('İzin talebi','leave-new','primary','plus')}</div>`}
function e360Attendance(e){const p=state.puantaj[e.id];const ots=state.overtime.filter(o=>o.emp===e.id);const sh=state.shifts.find(s=>s.id===(state.shiftPlan[e.id]||'sh2'));return `<section class="metrics">${metric('Ekim çalışma günü',p?.work??'—','puantaj','clock')}${metric('İzin / rapor',p?`${p.leave} / ${p.report}`:'—','gün','activity')}${metric('Fazla mesai',p?`${p.overtime} <small>saat</small>`:'—','onaylı + bekleyen','timer')}${metric('Eksik süre',p?`${p.missing} <small>saat</small>`:'—','düzeltme gerekebilir','flag')}</section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Vardiya / çalışma planı</h2></div><div class="panel-body">${kv([['Şablon',esc(sh?.name||'—')],['Saatler',esc(sh?.hours||'—')],['Mola',`${sh?.brk||0} dk`],['Günler',esc(sh?.days||'—')]])}<label class="form-field">Şablonu değiştir<select data-shift="${e.id}">${state.shifts.map(s=>option(s.id,s.name,sh?.id)).join('')}</select></label></div></div><div class="panel"><div class="panel-header"><h2>Fazla mesai talepleri</h2>${btn('Talep','ot-new','sm','plus',`data-id="${e.id}"`)}</div><div class="panel-body">${ots.map(o=>`<div class="toggle-row"><div><strong>${date(o.date)} · ${o.hours} saat</strong><small>${esc(o.reason)} · kanıt: ${esc(o.evidence)}</small></div>${badge(o.status)}</div>`).join('')||'<p class="empty">Talep yok.</p>'}</div></div></section><p class="small muted" style="margin-top:12px">Proje timesheet’i (görev eforu, JS Work/Resources) ile personel mesai kontrolü aynı şey değildir; burada yalnız devam/mesai tutulur.</p>`}
function payrollGate(key){if(!grant(key))return lockPanel(key==='can.read.payroll'?'Bordro belgeleri ayrı yetkidir':'Ücret verisi ayrı yetkidir','Payroll rolü (Bengisu Arda · bordro@) + step-up MFA gerekir; owner/İK otomatik görmez.',key);if(!stepUp())return `<section class="panel lock-panel"><div class="lock-icon">${ic('shield')}</div><h2>Step-up doğrulama gerekli</h2><p>Hassas veri sınıfı. Oturumun bu bölüm için ek doğrulama ister (10 dk geçerli); erişim olayı audit’e yazılır.</p>${btn('MFA ile doğrula','stepup','primary','shield')}</section>`;return ''}
function e360Payroll(e){if(!isSelf(e.id)){const g=payrollGate('can.read.payroll');if(g)return g}const docs=docsOf(e.id).filter(d=>d.category==='Bordro / ödeme belgesi');return `<div class="banner">${ic('shield')}<span>${isSelf(e.id)?'Kendi bordrolarını görüyorsun.':'Payroll yetkisi + step-up MFA ile açıldı; her görüntüleme/indirme Belge Erişim Kayıtları’na yazılır.'} Tutarlar demoda tutulmaz.</span></div>${docTable(docs,{canSee:true})}`}
function e360Comp(e){const g=payrollGate('can.read.compensation');if(g)return g;const crs=state.compReviews.filter(c=>c.emp===e.id);return `<section class="panel"><div class="panel-header"><h2>Ücret / prim geçmişi</h2>${badge('Maskeli tutar','danger')}</div><div class="panel-body">${tbl(['TARİH','TÜR','AÇIKLAMA','TUTAR'],[...(e.history||[]).filter(h=>h.type==='Ücret revizyonu').map(h=>`<tr><td>${date(h.at)}</td><td>${h.type}</td><td>Dönemsel revizyon</td><td class="mono">${MASK}</td></tr>`),...crs.map(c=>`<tr><td>${date(c.effective)}</td><td>${c.type}</td><td>${esc(c.proposal)} · ${badge(c.status)}</td><td class="mono">${MASK}</td></tr>`)].join(''),'Ücret geçmişi')}<p class="small muted">Yan haklar: yemek kartı, özel sağlık — kayıt modeli hazır; tutarlar bordro sisteminden onaylı veriyle gelir.</p></div></section>`}
function e360Assets(e){const as=state.hrAssets.filter(a=>a.emp===e.id);return tbl(['VARLIK','SERİ NO','TESLİM','İADE','DURUM','HASAR',''],as.map(a=>assetRow(a)).join(''),'Zimmetler')+`<div class="form-actions" style="justify-content:start">${canArchive()?btn('Zimmet ata','asset-assign','','plus',`data-id="${e.id}"`):''}</div>`}
function assetRow(a){const i=state.hrAssets.indexOf(a);return `<tr><td><strong>${esc(a.name)}</strong><br><small class="muted">${esc(a.type)}${a.emp?' · '+esc(empName(a.emp)):''}</small></td><td class="mono">${esc(a.serial)}</td><td>${date(a.delivered)}</td><td>${date(a.returned)}</td><td>${badge(a.status,a.status==='Zimmetli'?'success':a.status==='Depoda'?'neutral':'warn')}<br><small>${esc(a.condition)}</small></td><td>${a.damage.length?a.damage.map(d=>`<small>${date(d.at)} · ${esc(d.text)}</small>`).join('<br>'):'—'}</td><td class="actions nowrap">${a.status==='Zimmetli'?btn('İade al','asset-return','sm','refresh',`data-id="${a.id}"`)+btn('Hasar','asset-damage','sm','flag',`data-id="${a.id}"`):a.status!=='Zimmetli'&&canArchive()?btn('Ata','asset-assign','sm','arrow',`data-asset="${a.id}"`):''}</td></tr>`}
function e360Training(e){const recs=state.trainingRecords.filter(r=>r.emp===e.id);return tbl(['EĞİTİM','ZORUNLU','DURUM','TAMAMLANDI','SERTİFİKA · SON GEÇERLİLİK',''],recs.map(r=>{const t=state.trainings.find(x=>x.id===r.training);return `<tr><td><strong>${esc(t?.name)}</strong><br><small class="muted">${t?.hours} saat · yenileme ${esc(t?.renew)}</small></td><td>${t?.mandatory?badge('Zorunlu','warn'):'—'}</td><td>${badge(r.status)}</td><td>${date(r.completed)}</td><td>${r.cert?`${esc(r.cert)}<br><small class="${r.expires&&daysFromToday(r.expires)<=60?'warn-text':'muted'}">${date(r.expires)}</small>`:'—'}</td><td class="actions nowrap">${r.status==='Kayıtlı'?btn('Tamamlandı','tr-complete','sm primary','check',`data-id="${r.id}"`):r.expires&&daysFromToday(r.expires)<=60?btn('Yenile','cert-renew','sm','refresh',`data-id="${r.id}"`):''}</td></tr>`}).join(''),'Eğitimler')+`<div class="form-actions" style="justify-content:start"><label class="form-field">Eğitime kaydol<select data-enroll="${e.id}"><option value="">Seç…</option>${state.trainings.filter(t=>!recs.some(r=>r.training===t.id)).map(t=>option(t.id,t.name,'')).join('')}</select></label></div>`}
function e360Perf(e){if(!(grant('can.view.performance')||isSelf(e.id)||e.manager===selfId()))return lockPanel('Performans kayıtları özel yetkidir','İK, ilgili yönetici ve çalışanın kendisi görür. AI tek başına karar vermez.','can.view.performance');const r=state.perfReviews.find(x=>x.emp===e.id);if(!r)return `<section class="panel"><div class="panel-body"><p class="empty">Bu döngüde değerlendirme kaydı yok.</p>${btn('Döngüye ekle','perf-add','sm','plus',`data-id="${e.id}"`)}</div></section>`;const i=state.perfReviews.indexOf(r);const c=state.perfCycle;return `<div class="banner">${ic('info')}<span>${esc(c.name)} · aşama: <strong>${esc(c.stage)}</strong> · son tarih ${date(c.deadline)}. Adımlar: ${c.steps.join(' → ')}.</span></div><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Hedefler / OKR</h2>${badge(r.status)}</div><div class="panel-body">${r.goals.map((g,gi)=>`<div class="goal"><div class="goal-top"><span>${esc(g[0])}</span><strong>%${g[1]}</strong></div>${meter(g[1])}<input type="range" min="0" max="100" step="5" value="${g[1]}" data-goal="${i}:${gi}" aria-label="${esc(g[0])} ilerleme"></div>`).join('')}${btn('Hedef ekle','goal-add','sm','plus',`data-id="${i}"`)}</div></div><div class="panel"><div class="panel-header"><h2>Değerlendirme</h2></div><div class="panel-body"><form id="perf-form" data-id="${i}" class="form-grid"><label class="form-field full">Öz değerlendirme<textarea name="self" rows="3" ${isSelf(e.id)||canArchive()?'':'readonly'}>${esc(r.self)}</textarea></label><label class="form-field full">Yönetici geri bildirimi<textarea name="manager" rows="3" ${e.manager===selfId()||canArchive()||role()==='owner'?'':'readonly'}>${esc(r.manager)}</textarea></label><div class="form-actions full"><button class="button primary" type="submit">Kaydet ${ic('check')}</button></div></form></div></div></section>`}
function e360File(e){const on=e.onboarding||[],off=e.offboarding||[];const docs=docsOf(e.id).filter(d=>d.category==='Ayrılış dosyası');const ho=state.handover?.filter(h=>h.from===e.id||h.to===e.id)||[];const ws=state.wsRequests.filter(w=>w.emp===e.id);const list=(items,key)=>items.map((it,i)=>`<li><button class="check ${it[1]?'done':''}" data-action="ob-toggle" data-id="${e.id}" data-key="${key}" data-i="${i}" aria-pressed="${it[1]}" aria-label="${esc(it[0])}">${it[1]?ic('check'):''}</button><span>${esc(it[0])}</span></li>`).join('');return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>İşe giriş kontrol listesi</h2>${badge(`${on.filter(x=>x[1]).length}/${on.length}`,'neutral')}</div><div class="panel-body"><ul class="check-list">${list(on,'onboarding')||'<li class="muted">Onboarding tamamlandı / gerekmedi.</li>'}</ul>${ws.map(w=>`<div class="toggle-row"><div><strong>Google Workspace kullanıcısı</strong><small>${esc(w.email)} · ${esc(w.at)}</small></div>${badge(w.status)}</div>`).join('')}</div></div><div class="panel"><div class="panel-header"><h2>Ayrılış dosyası</h2>${e.end?badge(`son gün ${date(e.end)}`,'warn'):badge('—','neutral')}</div><div class="panel-body"><ul class="check-list">${list(off,'offboarding')||'<li class="muted">Offboarding yok.</li>'}</ul>${docs.length?docTable(docs):''}${e.status==='Ayrılıyor'&&canArchive()?`<div class="form-actions" style="justify-content:start">${btn('Ayrılışı tamamla (erişim kapat + arşivle)','emp-offboard','primary','lock',`data-id="${e.id}"`)}</div>`:''}</div></div></section>${ho.length?`<section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Devir planı</h2></div><div class="panel-body">${ho.map(h=>`<p><strong>${esc(empName(h.from))} → ${esc(empName(h.to))}</strong> · ${h.items.filter(x=>x[1]).length}/${h.items.length} tamamlandı · <a href="#people/onboarding">detay</a></p>`).join('')}</div></section>`:''}`}

/* ---------- Personel Arşivi ---------- */
function arcGate(){return canArchive()?'':lockPanel('Personel arşivi yalnız yetkili İK’ya görünür','Owner/admin dahil otomatik tam erişim yok (spec §17.2, §4.4). Erişim; yetkili görevlendirme, step-up MFA ve audit ile.','can.read.hr.archive')}
function arcFilters(){return `<div class="toolbar"><label class="form-field">Belge türü<select data-ui-sel="arcCat"><option value="">Tümü</option>${[...new Set(state.hrDocs.map(d=>d.category))].map(c=>option(c,c,ui.arcCat||'')).join('')}</select></label><label class="form-field">Durum<select data-ui-sel="arcStatus"><option value="">Tümü</option>${DOC_STATUSES.map(s=>option(s,s,ui.arcStatus||'')).join('')}</select></label><label class="form-field">Kaynak<select data-ui-sel="arcSrc"><option value="">Tümü</option>${['kolayik','jspeople','upload'].map(s=>option(s,s,ui.arcSrc||'')).join('')}</select></label>${btn('CSV','arc-csv','sm','download')}</div>`}
const arcFiltered=docs=>docs.filter(d=>(!ui.arcCat||d.category===ui.arcCat)&&(!ui.arcStatus||d.status===ui.arcStatus)&&(!ui.arcSrc||d.source_system===ui.arcSrc));
function arcActive(){const g=arcGate();if(g)return g;const list=state.employees.filter(e=>e.status!=='Ayrıldı');return arcFilters()+tbl(['ÇALIŞAN','DURUM','BELGE','TAMAMLANMA','EKSİK','SÜRESİ DOLAN','KAYNAK','SON ERİŞİM',''],list.map(e=>{const ds=arcFiltered(docsOf(e.id));const miss=ds.filter(d=>d.status==='Eksik').length,exp=ds.filter(d=>d.status==='Süresi doldu').length;const last=state.accessLog.find(a=>a.emp===e.id);return `<tr><td><strong>${esc(e.name)}</strong><br><small class="muted">${esc(e.title)}</small></td><td>${badge(e.status)}</td><td>${ds.length}</td><td>${meter(completion(e.id))}<small>%${completion(e.id)}</small></td><td>${miss?badge(miss,'danger'):'0'}</td><td>${exp?badge(exp,'danger'):'0'}</td><td><small class="mono">${[...new Set(ds.map(d=>d.source_system))].join(', ')}</small></td><td><small>${last?esc(last.at+' · '+last.who):'—'}</small></td><td>${btn('Dosya dolabı','arc-open','sm','files',`data-id="${e.id}"`)}</td></tr>`}).join(''),'Aktif personel arşivi')}
function arcFormer(){const g=arcGate();if(g)return g;const list=state.employees.filter(e=>e.status==='Ayrıldı');return `<div class="banner">${ic('info')}<span>Ayrılan personelin kartını kapatmak belgeleri silmez; arşiv yalnız yetkililere görünür ve kategori bazlı saklama/imha kurallarına tabidir. Erişim durdurulmuş, legal hold gerektiğinde uygulanır.</span></div>${list.map(e=>{const ds=docsOf(e.id);return `<section class="panel" style="margin-bottom:16px"><div class="panel-header"><h2>${esc(e.name)} <span class="muted small">${esc(e.title)} · ${date(e.start)} → ${date(e.end)}</span></h2><div class="actions">${badge('Erişim durduruldu','danger')}${badge(`${ds.length} belge`,'neutral')}${btn(ds.some(d=>d.legal_hold_flag)?'Legal hold kaldır':'Legal hold uygula','doc-hold','sm','lock',`data-id="${e.id}"`)}</div></div><div class="panel-body">${docTable(ds)}</div></section>`}).join('')||'<p class="empty">Eski personel kaydı yok.</p>'}`}
function arcTypes(){const g=arcGate();if(g)return g;const cats={};state.hrDocs.forEach(d=>{const k=d.category;cats[k]=cats[k]||{n:0,subs:new Set(),conf:d.confidentiality_level,ret:d.retention_policy,ai:d.aiIndex};cats[k].n++;cats[k].subs.add(d.subcategory)});return tbl(['KATEGORİ','ALT TÜRLER','BELGE','GİZLİLİK SINIFI','SAKLAMA','AI İNDEKSİ','ZORUNLU'],Object.entries(cats).map(([k,v])=>`<tr><td><strong>${esc(k)}</strong></td><td><small>${[...v.subs].slice(0,6).map(esc).join(', ')}${v.subs.size>6?' …':''}</small></td><td>${v.n}</td><td>${badge(v.conf,v.conf==='Özel nitelikli'||v.conf==='Bordro'?'danger':'neutral')}</td><td>${esc(v.ret)}</td><td>${v.ai?badge('Evet','success'):badge('Hayır (varsayılan)','danger')}</td><td>${['İşe giriş evrakı','Sözleşme & ek protokol','İmzalı formlar'].includes(k)?badge('Zorunlu','warn'):'—'}</td></tr>`).join(''),'Belge türleri')+`<div class="form-actions" style="justify-content:start">${btn('Belge türü ekle','doctype-add','','plus')}</div>`}
function arcMissing(){const g=arcGate();if(g)return g;const miss=arcFiltered(state.hrDocs.filter(d=>['Eksik','Yükleme talebi','HR onayı bekliyor','Reddedildi'].includes(d.status)));const exp=expiring(60);return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Eksik belgeler <span class="muted small">${miss.length}</span></h2>${btn('Tümüne yükleme talebi gönder','doc-request-all','sm primary','upload')}</div><div class="panel-body">${tbl(['ÇALIŞAN','BELGE','DURUM',''],miss.map(d=>`<tr><td>${esc(empName(d.employee_id))}</td><td>${esc(d.subcategory)}<br><small class="muted">${esc(d.category)}</small></td><td>${docBadge(d.status)}</td><td class="actions nowrap">${d.status==='Eksik'?btn('Talep','doc-request','sm','upload',`data-id="${d.id}"`):d.status==='Yükleme talebi'?btn('Çalışan yükledi (simüle)','doc-upload-ss','sm','upload',`data-id="${d.id}"`):d.status==='HR onayı bekliyor'?btn('Onayla','doc-approve','sm primary','check',`data-id="${d.id}"`)+btn('Reddet','doc-reject','sm','close',`data-id="${d.id}"`):''}</td></tr>`).join(''),'Eksik belgeler')}<p class="small muted">Akış: Eksik → self-servis yükleme talebi (My People) → çalışan yükler → HR onayı → Mevcut. Reddedilen belge yeniden talep edilir.</p></div></div><div class="panel"><div class="panel-header"><h2>Süresi dolan / dolacak (60 gün) <span class="muted small">${exp.length}</span></h2>${btn('Hatırlatma üret','doc-remind','sm','bell')}</div><div class="panel-body">${tbl(['ÇALIŞAN','BELGE','SON GEÇERLİLİK',''],exp.map(d=>`<tr><td>${esc(empName(d.employee_id))}</td><td>${esc(d.subcategory)}</td><td class="${daysFromToday(d.expires_at)<0?'danger-text':'warn-text'}">${date(d.expires_at)} (${daysFromToday(d.expires_at)} gün)</td><td>${btn('Yenile (yeni sürüm)','doc-replace','sm','refresh',`data-id="${d.id}"`)}</td></tr>`).join(''),'Süresi dolacak belgeler')}</div></div></section>`}
function arcBulk(){const g=arcGate();if(g)return g;return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Toplu içe aktarım</h2>${badge('CSV / Excel / Kolay İK export','neutral')}</div><div class="panel-body"><p class="small muted">Alan eşleme önizlemesi: kaynak sütun → JS People alanı. Her kayıt source_system, source_record_id ve import_batch_id ile gelir; tekrar çalıştırma idempotenttir.</p>${tbl(['KAYNAK SÜTUN','HEDEF ALAN','ÖRNEK'],[['employee_no','employee.externalId','kik_p_1004'],['document_type','employee_document.category','İşe giriş evrakı'],['file_name','original_filename','SK_diploma_2020.pdf'],['issued_at','document_date','2020-04-01'],['valid_until','expires_at','—'],['sha256','sha256_checksum','9f2a…c41e']].map(r=>`<tr>${r.map(c=>`<td class="mono">${esc(c)}</td>`).join('')}</tr>`).join(''),'Alan eşleme')}<div class="form-actions" style="justify-content:start"><label class="button">${ic('upload')}<span>CSV seç</span><input type="file" id="hr-import-file" accept=".csv,.xlsx,.json" hidden></label>${btn('Örnek paketi içe aktar (simüle)','hr-import-sim','primary','refresh')}</div></div></div><div class="panel"><div class="panel-header"><h2>Dışa aktarım</h2>${badge(grant('can.export.hr')?'Yetkili':'Açık yetki gerekir',grant('can.export.hr')?'success':'danger')}</div><div class="panel-body"><p class="small muted">Dışa aktarım yetkisi ayrıdır; bordro ve özel nitelikli belgeler pakete girmez. Her dışa aktarım audit’e yazılır.</p><div class="actions">${btn('Belge metadata CSV','arc-csv','','download')}${btn('Personel listesi CSV','emp-csv','','download')}${btn('Arşiv paketi (JSON)','arc-json','','download')}</div></div></div></section>`}
function arcRetention(){const g=arcGate();if(g)return g;return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Saklama politikaları</h2></div><div class="panel-body">${tbl(['KATEGORİ','SÜRE','SÜRE SONU İŞLEMİ'],state.retentionPolicies.map(r=>`<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td><td><small>${esc(r[2])}</small></td></tr>`).join(''),'Saklama')}</div></div><div class="panel"><div class="panel-header"><h2>İmha kuyruğu</h2>${badge(`${state.disposalQueue.length}`,'neutral')}</div><div class="panel-body">${state.disposalQueue.map(q=>`<div class="toggle-row"><div><strong>${esc(q.doc)}</strong><small>${esc(empName(q.emp))} · politika ${esc(q.policy)} · süre sonu ${date(q.due)}${q.hold?' · LEGAL HOLD':''}</small></div><div class="actions">${badge(q.status)}${q.status==='İmha onayı bekliyor'?btn('İmha onayı iste','disposal-request','sm','approvals',`data-id="${q.id}"`):q.status==='Onay bekliyor (Onay Merkezi)'?badge('Onay Merkezi’nde','warn'):''}${q.status==='Onaylandı'?btn('İmha et (değiştirilemez kayıt)','disposal-execute','sm primary','trash',`data-id="${q.id}"`):''}</div></div>`).join('')||'<p class="empty">Kuyruk boş.</p>'}<p class="small muted">Legal hold altındaki belge imha edilemez. İmha; kim/ne zaman/hangi politika ile değiştirilemez iz bırakır.</p></div></div></section>`}
function arcAccess(){const g=arcGate();if(g)return g;const f=ui.accFilter||'';const rows=state.accessLog.filter(a=>!f||a.action.startsWith(f));return `<div class="toolbar"><label class="form-field">İşlem<select data-ui-sel="accFilter"><option value="">Tümü</option>${['görüntüledi','indirdi','değiştirdi'].map(a=>option(a,a,f)).join('')}</select></label>${btn('CSV','access-csv','sm','download')}</div>${tbl(['ZAMAN','KİM','ROL','BELGE','ÇALIŞAN','İŞLEM'],rows.map(a=>`<tr><td class="mono">${esc(a.at)}</td><td>${esc(a.who)}</td><td>${esc(a.role)}</td><td class="mono">${esc(a.doc)}</td><td>${esc(empName(a.emp))}</td><td>${badge(a.action.split(' ')[0],a.action.startsWith('değiştirdi')?'warn':'neutral')} ${esc(a.action.replace(/^\S+\s?/,''))}</td></tr>`).join(''),'Belge erişim kayıtları')}<p class="small muted">Kim görüntüledi / indirdi / değiştirdi; kaynak dosya checksum’ı ile değiştirilemez iz. Kayıtlar 180 gün tutulur.</p>`}
function logAccess(d,action){state.accessLog.unshift({at:new Date().toLocaleString('tr-TR'),who:account().name,role:roleLabel[role()],doc:d.id,emp:d.employee_id,action});state.accessLog=state.accessLog.slice(0,200)}
function docDialog(id){const d=state.hrDocs.find(x=>x.id===id);if(!d)return;logAccess(d,'görüntüledi');log(`Belge görüntülendi: ${d.subcategory} (${empName(d.employee_id)}) · ${d.id}`);openDialog(esc(d.subcategory),`<div class="dialog-body"><div class="actions">${docBadge(d.status)}${badge(d.confidentiality_level,'neutral')}${badge('source: '+d.source_system,'neutral')}${d.legal_hold_flag?badge('LEGAL HOLD','danger'):''}</div><div class="doc-preview"><span>${esc(d.original_filename)}</span><small>Önizleme (demo) · ${(d.file_size/1024).toFixed(0)} KB · ${esc(d.mime_type)}</small></div>${kv([['document_id',`<code class="mono">${d.id}</code>`],['employee_id',`${esc(empName(d.employee_id))} <code class="mono">${d.employee_id}</code>`],['category / subcategory',`${esc(d.category)} / ${esc(d.subcategory)}`],['source_system / source_record_id',`${esc(d.source_system)} / ${esc(d.source_record_id||'—')}`],['document_date / effective_from',`${d.document_date} / ${d.effective_from}`],['expires_at',d.expires_at||'—'],['retention_policy',esc(d.retention_policy)],['confidentiality_level',esc(d.confidentiality_level)],['version_number',`v${d.version_number}${d.versions.length?` · önceki: ${d.versions.map(v=>'v'+v.version_number).join(', ')}`:''}`],['sha256_checksum',`<code class="mono">${d.sha256_checksum}</code>`],['storage_object_key',`<code class="mono">${d.storage_object_key}</code>`],['uploaded_by / import_batch_id',`${esc(d.uploaded_by)} / ${esc(d.import_batch_id||'—')}`],['created_at / deleted_at',`${d.created_at} / ${d.deleted_at||'—'}`],['legal_hold_flag',String(d.legal_hold_flag)],['AI indeksi',d.aiIndex?'evet':'hayır (hassas sınıf)']])}<div class="form-actions">${btn('İndir (kontrollü)','doc-download','','download',`data-id="${d.id}"`)}${canArchive()?btn('Yeni sürüm yükle','doc-replace','','upload',`data-id="${d.id}"`)+btn(d.legal_hold_flag?'Legal hold kaldır':'Legal hold','doc-hold-one','','lock',`data-id="${d.id}"`):''}${btn('Kapat','close','primary','check')}</div></div>`)}

/* ---------- İzin merkezi ---------- */
function leaveCal(list){const days=[...Array(28)].map((_,i)=>{const d=new Date('2026-10-12T12:00:00');d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)});const hol=Object.fromEntries(state.holidays);const conflicts=new Set();state.leaves.filter(l=>l.status!=='Reddedildi').forEach(a=>state.leaves.forEach(b=>{if(a!==b&&a.person!==b.person&&emp(a.person)?.team===emp(b.person)?.team&&a.from<=b.to&&b.from<=a.to){conflicts.add(a.id);conflicts.add(b.id)}}));return `<div class="panel table-wrap" tabindex="0" role="region" aria-label="İzin takvimi"><table class="leave-cal"><thead><tr><th>KİŞİ</th>${days.map(d=>`<th class="${['6','0'].includes(String(new Date(d+'T12:00:00').getDay()))?'wk':''} ${hol[d]?'hol':''}" title="${esc(hol[d]||'')}">${d.slice(8)}</th>`).join('')}</tr></thead><tbody>${list.map(e=>`<tr><td>${esc(e.name)}<br><small class="muted">${esc(e.team)}</small></td>${days.map(d=>{const l=state.leaves.find(x=>x.person===e.id&&x.from<=d&&x.to>=d&&x.status!=='Reddedildi');const wk=['6','0'].includes(String(new Date(d+'T12:00:00').getDay()));const hy=e.location?.includes('Hibrit')&&['2','4'].includes(String(new Date(d+'T12:00:00').getDay()));return `<td class="${wk?'wk':''} ${hol[d]?'hol':''} ${l?(l.status==='Onaylandı'?'on':'pend'):''} ${l&&conflicts.has(l.id)?'conf':''} ${hy&&!l?'office':''}" title="${l?esc(l.type+' · '+l.status+(conflicts.has(l.id)?' · ÇAKIŞMA (aynı ekip)':'')):hol[d]?esc(hol[d]):hy?'Ofis günü':''}">${l?(conflicts.has(l.id)?'!':'•'):''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="heat-legend"><span><i class="on"></i>Onaylı</span><span><i class="pend"></i>Bekliyor</span><span><i class="conf"></i>Aynı ekipte çakışma</span><span><i class="hol"></i>Resmî tatil</span><span><i class="office"></i>Hibrit ofis günü (Sal/Per)</span></div>`}
function peopleLeaveCenter(){const mgr=role()==='manager';const list=(mgr?myTeam():state.employees).filter(e=>e.status!=='Ayrıldı');const reqs=state.leaves.filter(l=>list.some(e=>e.id===l.person)).sort((a,b)=>a.status==='Bekliyor'?-1:1);return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>İzin talepleri</h2>${badge(`${reqs.filter(r=>r.status==='Bekliyor').length} bekliyor`,'warn')}</div><div class="panel-body">${tbl(['KİŞİ','TÜR','TARİH','GÜN','VEKİL','ADIM','DURUM',''],reqs.map(l=>{const i=state.leaves.indexOf(l);const canMgr=l.step==='Yönetici'&&(emp(l.person)?.manager===selfId()||role()==='owner'||role()==='hr');const canHr=l.step==='İK'&&(role()==='hr'||role()==='owner');return `<tr><td><strong>${esc(empName(l.person))}</strong></td><td>${esc(l.type)}</td><td>${date(l.from)}–${date(l.to)}</td><td>${l.days||1}</td><td>${l.status==='Bekliyor'?`<select data-leave-deputy="${i}" aria-label="Vekil"><option value="">—</option>${state.employees.filter(e=>e.id!==l.person&&e.status==='Aktif').map(e=>option(e.id,e.name,l.deputy)).join('')}</select>`:esc(l.deputy?empName(l.deputy):'—')}</td><td>${l.status==='Bekliyor'?badge(l.step,'warn'):'—'}</td><td>${badge(l.status)}</td><td class="actions nowrap">${l.status==='Bekliyor'&&(canMgr||canHr)?btn(l.step==='Yönetici'?'Yönetici onayı':'İK onayı','leave-step','sm primary','check',`data-id="${l.id}"`)+btn('Reddet','leave-reject','sm','close',`data-id="${l.id}"`):''}</td></tr>`}).join(''),'İzin talepleri')}<p class="small muted">Akış: çalışan talebi → birim yöneticisi → İK onayı (yapılandırılabilir). Onaylı izin JS Resources kapasitesinden düşer; çakışan görev tarihleri işaretlenir, vekil önerilir (akış 7.3).</p></div></div><div class="panel"><div class="panel-header"><h2>İzin türleri & kurallar</h2></div><div class="panel-body">${tbl(['TÜR','ÜCRETLİ','KURAL'],state.leaveTypes.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td>${t.paid?badge('Evet','success'):badge('Hayır','neutral')}</td><td><small>${esc(t.rule)}</small></td></tr>`).join(''),'İzin türleri')}<p class="small muted">Resmî tatiller: ${state.holidays.map(h=>`${date(h[0])} ${esc(h[1])}`).join(' · ')}. Hibrit günler: Sal/Per ofis.</p></div></div></section><section class="panel" style="margin:20px 0"><div class="panel-header"><h2>Bakiyeler</h2>${badge('Hak ediş + hareket + kalan','neutral')}</div><div class="panel-body">${tbl(['KİŞİ','KIDEM','HAK EDİŞ','AÇILIŞ','KULLANILAN','BEKLEYEN','KALAN'],list.filter(e=>e.status!=='Teyit bekliyor').map(e=>{const used=(e.leaveUsed||0);const pend=state.leaves.filter(l=>l.person===e.id&&l.status==='Bekliyor'&&l.type==='Yıllık izin').reduce((s,l)=>s+(l.days||1),0);const tot=entitlement(e)+(e.leaveOpening||0);return `<tr><td>${esc(e.name)}</td><td>${kidem(e)} yıl</td><td>${entitlement(e)}</td><td>${e.leaveOpening||0}</td><td>${used}</td><td>${pend||'—'}</td><td><strong>${Math.max(0,tot-used)}</strong></td></tr>`}).join(''),'İzin bakiyeleri')}</div></div></section>${leaveCal(list)}`}
function applyLeave(l){const e=emp(l.person);if(!e)return [];const days=l.days||1;const wk=Math.max(0,Math.min(5,Math.floor((new Date(l.from)-new Date('2026-10-12'))/604800000)));if(state.capacity?.[l.person])state.capacity[l.person][wk]=Math.max(0,(state.capacity[l.person][wk]||40)-days*8);if(l.type==='Yıllık izin')e.leaveUsed=(e.leaveUsed||0)+days;const conflicts=state.tasks.filter(t=>!t.done&&t.owner===l.person&&t.due>=l.from&&t.due<=l.to);conflicts.forEach(t=>{t.leaveConflict=l.id;t.labels=[...new Set([...(t.labels||[]),'izin çakışması'])]});const team=state.employees.filter(x=>x.team===e.team&&x.id!==e.id&&x.status==='Aktif');const dep=l.deputy||team.sort((a,b)=>(state.capacity?.[a.id]?.[wk]||40)-(state.capacity?.[b.id]?.[wk]||40))[0]?.id||state.employees.filter(x=>x.id!==e.id&&x.status==='Aktif').sort((a,b)=>(state.capacity?.[a.id]?.[wk]||40)-(state.capacity?.[b.id]?.[wk]||40))[0]?.id||'';l.deputy=dep;state.hrDocs.push({id:`D-${e.id}-LV${Date.now().toString(36)}`,organization_id:'org_jobs',employee_id:e.id,category:'İzin evrakı',subcategory:`${l.type} onayı · ${l.from}`,original_filename:`${e.id}_izin_${l.from}.pdf`,mime_type:'application/pdf',file_size:48000,storage_object_key:`hr/${e.id}/izin_${l.from}.pdf`,sha256_checksum:fakeSha(l.id+l.from),source_system:'jspeople',source_record_id:l.id,document_date:TODAY,effective_from:l.from,expires_at:'',retention_policy:'5 yıl',confidentiality_level:'Standart',version_number:1,uploaded_by:account().person,import_batch_id:'',created_at:TODAY,deleted_at:'',legal_hold_flag:false,status:'Mevcut',versions:[],aiIndex:true});emit('leave.approved',`leave:${l.id}`);if(conflicts.length)addNotification(`${e.name} izni ${conflicts.length} görevle çakışıyor; vekil önerisi: ${empName(dep)}.`,'resources/planner');addNotification(`${e.name} izni onaylandı · kapasite ${days*8} saat düşüldü.`,'resources/kapasite');return conflicts}

/* ---------- Mesai / Puantaj / Vardiya / PDKS ---------- */
function peopleAttendance(){const pz=state.puantaj;const rows=activeEmps().filter(e=>pz[e.id]).map(e=>{const p=pz[e.id];return `<tr><td><strong>${esc(e.name)}</strong></td><td>${p.work}</td><td>${p.leave}</td><td>${p.report}</td><td>${p.overtime}</td><td>${p.missing?badge(p.missing+' saat','danger'):'0'}</td><td>${badge(p.status,p.status==='Açık'?'warn':'success')}</td><td class="actions nowrap">${p.status==='Açık'?btn('Düzelt','puantaj-fix','sm','settings',`data-id="${e.id}"`)+(role()==='hr'||role()==='owner'?btn('İK onayı','puantaj-approve','sm primary','check',`data-id="${e.id}"`):''):''}</td></tr>`}).join('');const allOk=Object.values(pz).every(p=>p.status!=='Açık');return `<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Aylık puantaj · Ekim 2026</h2><div class="actions">${badge(allOk?'İK onaylı · bordroya hazır':'İK onayı bekliyor',allOk?'success':'warn')}${btn('Bordroya gönder','puantaj-send','sm '+(allOk?'primary':''),'arrow',allOk?'':'disabled')}</div></div><div class="panel-body">${tbl(['KİŞİ','ÇALIŞMA GÜNÜ','İZİN','RAPOR','FAZLA MESAİ (s)','EKSİK SÜRE','DURUM',''],rows,'Puantaj')}<p class="small muted">İK onayından önce bordroya kesin veri gönderilmez. Görev eforu (JS Work timesheet) ile mesai kontrolü ayrıdır.</p></div></section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Fazla mesai talepleri</h2>${btn('Talep','ot-new','sm','plus')}</div><div class="panel-body">${tbl(['KİŞİ','TARİH','SAAT','GEREKÇE','KANIT','DURUM',''],state.overtime.map(o=>`<tr><td>${esc(empName(o.emp))}</td><td>${date(o.date)}</td><td>${o.hours}</td><td><small>${esc(o.reason)}</small></td><td><small>${esc(o.evidence)}</small></td><td>${badge(o.status)}</td><td class="actions nowrap">${o.status==='Bekliyor'?btn('Onayla','ot-approve','sm primary','check',`data-id="${o.id}"`)+btn('Reddet','ot-reject','sm','close',`data-id="${o.id}"`):''}</td></tr>`).join(''),'Fazla mesai')}</div></div><div class="panel"><div class="panel-header"><h2>Vardiya şablonları</h2>${btn('Şablon ekle','shift-add','sm','plus')}</div><div class="panel-body">${tbl(['ŞABLON','SAAT','MOLA','GÜNLER','LOKASYON','ATANAN'],state.shifts.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.hours)}</td><td>${s.brk} dk</td><td><small>${esc(s.days)}</small></td><td>${esc(s.location)}</td><td>${Object.entries(state.shiftPlan).filter(([,v])=>v===s.id).map(([k])=>esc(empName(k))).join(', ')||(s.id==='sh2'?'varsayılan':'—')}</td></tr>`).join(''),'Vardiyalar')}<p class="small muted">Değişim talepleri ve lokasyon bazlı planlama; çekim/etkinlik günleri JS Events takviminden gelir.</p></div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>PDKS (giriş/çıkış)</h2>${badge('Opsiyonel · yasal değerlendirme gerekir','warn')}</div><div class="panel-body"><p>PDKS cihazı / QR / mobil uygulama ile çalışma girişi, kişisel veri işleme dayanağı ve çalışan aydınlatması değerlendirilmeden açılmaz. Ham hassas izleme minimize edilir; yalnız giriş/çıkış zaman damgası tutulur.</p><div class="form-grid"><label class="form-field">Kaynak${sel('pdks.source',['QR kod','Mobil uygulama','Cihaz (turnike)','Google Calendar (pasif)'],state.pdks.source)}</label><div class="form-field">Durum<div class="toggle-row" style="border:0;padding:6px 0"><span>${state.pdks.enabled?'Etkin (pilot)':'Kapalı'}</span>${sw('pdks.enabled',state.pdks.enabled,'PDKS pilotu')}</div></div></div><p class="small muted">Etkinleştirme bir yapılandırma kaydıdır; gerçek cihaz entegrasyonu yoktur.</p></div></section>`}

/* ---------- Masraf / Avans ---------- */
function peopleExpenses(){const mine=role()==='creative';const claims=state.expenseClaims.filter(x=>!mine||x.emp===selfId());return `<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Masraf talepleri</h2>${btn('Yeni masraf','exp-new','sm primary','plus')}</div><div class="panel-body">${tbl(['KİŞİ','KATEGORİ','TUTAR','PROJE / MALİYET MERKEZİ','FİŞ','ADIM','DURUM',''],claims.map(x=>`<tr><td><strong>${esc(empName(x.emp))}</strong><br><small class="muted">${date(x.date)} · ${esc(x.note)}</small></td><td>${esc(x.category)}</td><td>${x.currency==='TRY'?money(x.amount):`${x.amount} ${x.currency} × ${x.rate} = ${money(x.amount*x.rate)}`}</td><td>${x.project?esc(project(x.project)?.name):'—'}<br><small class="muted">${esc(x.costCenter)}</small></td><td><small class="mono">${esc(x.receipt)}</small></td><td>${x.status==='Bekliyor'?badge(x.step,'warn'):'—'}</td><td>${badge(x.status)}${x.financeExpenseId?`<br><small class="muted">Finance: ${esc(x.financeExpenseId)}</small>`:''}</td><td class="actions nowrap">${x.status==='Bekliyor'&&!mine?btn(x.step==='Yönetici'?'Yönetici onayı':x.step==='Finans'?'Finans onayı':'Öde','exp-step','sm primary','check',`data-id="${x.id}"`)+btn('Reddet','exp-reject','sm','close',`data-id="${x.id}"`):x.status==='Onaylandı'&&!mine?btn('Ödendi işaretle','exp-step','sm','check',`data-id="${x.id}"`):''}</td></tr>`).join(''),'Masraflar')}<p class="small muted">Çok aşamalı onay: Yönetici → Finans → Ödeme. Finans onayında masraf JS Finance’te <strong>tek bir</strong> gider kaydına dönüşür (idempotent: financeExpenseId). Limit: 5.000 TL üstü Seviye 1.</p></div></section><section class="panel"><div class="panel-header"><h2>Avanslar & mahsup</h2>${btn('Avans talebi','adv-new','sm','plus')}</div><div class="panel-body">${tbl(['KİŞİ','TUTAR','TARİH','KALAN','DURUM',''],state.advances.map(a=>`<tr><td>${esc(empName(a.emp))}<br><small class="muted">${esc(a.note)}</small></td><td>${money(a.amount)}</td><td>${date(a.date)}</td><td>${money(a.remaining)}</td><td>${badge(a.status,a.status==='Açık'?'warn':'success')}</td><td>${a.remaining>0?btn('Masraftan mahsup et','adv-settle','sm','refresh',`data-id="${a.id}"`):''}</td></tr>`).join(''),'Avanslar')}</div></section>`}
function expDialog(){openDialog('Masraf formu',`<form class="dialog-body" id="exp-form"><div class="form-grid"><label class="form-field">Kişi<select name="emp">${activeEmps().map(e=>option(e.id,e.name,selfId())).join('')}</select></label><label class="form-field">Kategori<select name="category">${['Ulaşım','Yemek','Konaklama','Yazılım','Malzeme','Temsil','Diğer'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="form-field">Tutar<input type="number" name="amount" min="1" step="0.01" required value="320"></label><label class="form-field">Para birimi / kur<select name="currency"><option>TRY</option><option>USD</option><option>EUR</option></select></label><label class="form-field">Kur (TRY)<input type="number" name="rate" step="0.01" value="1"></label><label class="form-field">Proje<select name="project"><option value="">—</option>${state.projects.map(p=>option(p.id,p.name,'')).join('')}</select></label><label class="form-field">Maliyet merkezi<select name="cc">${['Kreatif','Müşteri','Prodüksiyon','Operasyon','Etkinlik'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="form-field">Fiş / fatura<input name="receipt" placeholder="fis_2026_10_14.jpg" value="fis_${Date.now().toString(36)}.jpg"></label><label class="form-field full">Açıklama<input name="note" required placeholder="Ne için?"></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Onaya gönder ${ic('check')}</button></div></form>`)}

/* ---------- Zimmet / Eğitim ---------- */
function peopleAssetsReg(){const f=ui.assetF||'';const list=state.hrAssets.filter(a=>!f||a.status===f);return `<div class="toolbar"><label class="form-field">Durum<select data-ui-sel="assetF"><option value="">Tümü</option>${['Zimmetli','Depoda','İade edildi','Serviste'].map(s=>option(s,s,f)).join('')}</select></label>${btn('Varlık ekle','asset-new','sm','plus')}${btn('CSV','asset-csv','sm','download')}</div>${tbl(['VARLIK','SERİ NO','TESLİM','İADE','DURUM','HASAR',''],list.map(assetRow).join(''),'Varlık kaydı')}<p class="small muted">Ayrılan çalışan için otomatik iade/erişim kapatma kontrol listesi İşe Giriş / Ayrılış’ta; JS Resources ekipman rezervasyonu ve JS Finance amortisman referansı bağlıdır.</p>`}
function peopleTraining(){return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Eğitim kataloğu</h2>${btn('Eğitim ekle','tr-add','sm','plus')}</div><div class="panel-body">${tbl(['EĞİTİM','ZORUNLU','SÜRE','YENİLEME','KAYIT / TAMAMLANAN'],state.trainings.map(t=>{const r=state.trainingRecords.filter(x=>x.training===t.id);return `<tr><td><strong>${esc(t.name)}</strong></td><td>${t.mandatory?badge('Zorunlu','warn'):'—'}</td><td>${t.hours} s</td><td>${esc(t.renew)}</td><td>${r.length} / ${r.filter(x=>x.status==='Tamamlandı').length}</td></tr>`}).join(''),'Eğitimler')}</div></div><div class="panel"><div class="panel-header"><h2>Sertifikalar & yenileme</h2></div><div class="panel-body">${tbl(['KİŞİ','SERTİFİKA','SON GEÇERLİLİK',''],state.trainingRecords.filter(r=>r.cert).sort((a,b)=>a.expires.localeCompare(b.expires)).map(r=>`<tr><td>${esc(empName(r.emp))}</td><td>${esc(r.cert)}</td><td class="${daysFromToday(r.expires)<=60?'warn-text':''}">${date(r.expires)}</td><td>${daysFromToday(r.expires)<=60?btn('Yenile','cert-renew','sm','refresh',`data-id="${r.id}"`):''}</td></tr>`).join(''),'Sertifikalar')}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Kayıtlar</h2></div><div class="panel-body">${tbl(['KİŞİ','EĞİTİM','DURUM','TAMAMLANDI',''],state.trainingRecords.map(r=>`<tr><td>${esc(empName(r.emp))}</td><td>${esc(state.trainings.find(t=>t.id===r.training)?.name)}</td><td>${badge(r.status)}</td><td>${date(r.completed)}</td><td>${r.status==='Kayıtlı'?btn('Tamamlandı','tr-complete','sm','check',`data-id="${r.id}"`):''}</td></tr>`).join(''),'Eğitim kayıtları')}</div></section>`}

/* ---------- Performans / Ücret / Bordro ---------- */
function peoplePerf(){const c=state.perfCycle;return `<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>${esc(c.name)}</h2><div class="actions">${badge(c.stage,'warn')}${btn('Sonraki aşama','perf-advance','sm','arrow')}</div></div><div class="panel-body"><div class="steps">${c.steps.map((s,i)=>`<span class="step ${c.steps.indexOf(c.stage)>=i?'done':''}">${i+1}. ${s}</span>`).join('')}</div><p class="small muted">Öz değerlendirme → yönetici geri bildirimi → hedef/OKR → gelişim planı. 360° opsiyonel ve ayrı izinle. AI tek başına nihai karar vermez.</p></div></section><div class="project-grid">${state.perfReviews.map(r=>{const e=emp(r.emp);return `<article class="panel contract-card"><div class="card-top"><div><h2>${esc(e?.name)}</h2><small>${esc(e?.title)} · yönetici ${esc(empName(e?.manager))}</small></div>${badge(r.status)}</div>${r.goals.map(g=>`<div class="goal"><div class="goal-top"><span>${esc(g[0])}</span><strong>%${g[1]}</strong></div>${meter(g[1])}</div>`).join('')}<p class="small">${r.self?'Öz değerlendirme: '+esc(r.self):'<span class="muted">Öz değerlendirme bekleniyor</span>'}</p><div class="actions">${btn('Değerlendirmeyi aç','e360-goto','sm','arrow',`data-id="${r.emp}" data-tab="performans"`)}</div></article>`}).join('')}</div><div class="form-actions" style="justify-content:start"><label class="form-field">Döngüye çalışan ekle<select data-perf-add><option value="">Seç…</option>${activeEmps().filter(e=>!state.perfReviews.some(r=>r.emp===e.id)).map(e=>option(e.id,e.name,'')).join('')}</select></label></div>`}
function peopleComp(){const g=payrollGate('can.read.compensation');if(g)return g;return `<section class="panel"><div class="panel-header"><h2>Ücret değerlendirme önerileri</h2>${btn('Yeni öneri','comp-new','sm primary','plus')}</div><div class="panel-body">${tbl(['ÇALIŞAN','TÜR','ÖNERİ','TUTAR','YÜRÜRLÜK','ADIM','DURUM',''],state.compReviews.map(c=>`<tr><td><strong>${esc(empName(c.emp))}</strong></td><td>${esc(c.type)}</td><td><small>${esc(c.proposal)}</small></td><td class="mono">${MASK}</td><td>${date(c.effective)}</td><td>${['Taslak','Onay bekliyor'].includes(c.status)?badge(c.step,'warn'):'—'}</td><td>${badge(c.status)}</td><td class="actions nowrap">${c.status==='Taslak'?btn('Onaya gönder','comp-submit','sm primary','arrow',`data-id="${c.id}"`):c.status==='Onay bekliyor'?badge('Onay Merkezi’nde','warn'):''}</td></tr>`).join(''),'Ücret değerlendirme')}<p class="small muted">Bütçe simülasyonu: öneriler toplam ücret bütçesinin %${(2.4).toLocaleString('tr-TR')}’ü (anonim toplulaştırma). Çok aşamalı onay: Yönetici → Owner; onay bildirimi tutar içermez. Tarihsel iz Çalışan 360 → Ücret/Prim’de.</p></div></section>`}
function peoplePayroll(){const g=payrollGate('can.read.payroll');if(g)return g;const m=ui.payMonth||'2026-09';const run=state.payrollRuns.find(r=>r.month===m);const docs=state.hrDocs.filter(d=>d.category==='Bordro / ödeme belgesi'&&d.subcategory.endsWith(m));return `<div class="banner">${ic('shield')}<span>Payroll Vault · step-up doğrulandı (${Math.max(0,Math.round((state.stepUp.until-Date.now())/60000))} dk). Tutar, banka ve hesaplama yok; yalnız bordro PDF referansları. Her görüntüleme/indirme Belge Erişim Kayıtları’na yazılır.</span></div><div class="toolbar"><label class="form-field">Dönem<select data-ui-sel="payMonth">${state.payrollRuns.map(r=>option(r.month,`${r.month} · ${r.status}`,m)).join('')}</select></label>${run?.status.startsWith('Hazır')&&grant('can.publish.payroll')?btn('Çalışanlara yayımla + bildir','payroll-publish','sm primary','bell',`data-id="${m}"`):''}${btn('Dönem PDF’lerini içe aktar (Kolay İK)','payroll-import','sm','upload')}</div>${tbl(['ÇALIŞAN','BELGE','DURUM','CHECKSUM',''],docs.map(d=>`<tr><td><strong>${esc(empName(d.employee_id))}</strong></td><td class="mono">${esc(d.original_filename)}</td><td>${badge(run?.status.startsWith('Yayım')?'Yayımlandı':'Taslak')}</td><td class="mono"><small>${d.sha256_checksum}</small></td><td class="actions nowrap">${btn('Aç','doc-open','sm','eye',`data-id="${d.id}"`)}${btn('İndir','doc-download','sm','download',`data-id="${d.id}"`)}</td></tr>`).join(''),'Bordro belgeleri')}`}
function stepUpDialog(){openDialog('Step-up doğrulama (MFA)',`<form class="dialog-body" id="stepup-form"><div class="banner">${ic('shield')}<span>Hassas veri sınıfı (bordro/ücret). Authenticator uygulamasındaki 6 haneli kodu gir. Demo: herhangi 6 rakam kabul edilir; gerçek MFA yoktur.</span></div><label class="form-field full">Doğrulama kodu<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required placeholder="000000" autocomplete="one-time-code"></label><p class="small muted">Doğrulama 10 dakika geçerlidir; olay audit’e yazılır (kim, ne zaman, hangi kapsam).</p><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Doğrula ${ic('check')}</button></div></form>`);setTimeout(()=>$('#stepup-form [name=code]')?.focus(),30)}

/* ---------- İşe giriş / ayrılış, HR Reports, Kolay İK ---------- */
function peopleOnOff(){return `<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Google Workspace kullanıcı talepleri</h2>${badge('Ayrı admin politikası','neutral')}</div><div class="panel-body">${tbl(['ÇALIŞAN','E-POSTA','TARİH','DURUM',''],state.wsRequests.map(w=>`<tr><td>${esc(empName(w.emp))}</td><td class="mono">${esc(w.email)}</td><td>${esc(w.at)}</td><td>${badge(w.status)}</td><td>${w.status.startsWith('Admin')&&role()==='owner'?btn('Admin onayı (Workspace kullanıcısı aç)','ws-approve','sm primary','check',`data-id="${w.id}"`):''}</td></tr>`).join(''),'Workspace talepleri')}<p class="small muted">JS Hire → kabul edilen aday → çalışan kartı + davet; Workspace kullanıcısı açma yetkisi ayrı admin politikasıyla yürür (akış 7.2).</p></div></section>${peopleOnboard()}<h2 style="margin:24px 0 12px">Devir planı</h2>${peopleHandover()}`}
function peopleReports(){const teams=[...new Set(activeEmps().map(e=>e.team))];const hc=teams.map(t=>[t,activeEmps().filter(e=>e.team===t).length]);const exits=state.employees.filter(e=>e.end&&e.end>='2026-01-01').length;const avg=activeEmps().length;const turnover=avg?Math.round(exits/avg*100):0;const absence=Object.values(state.puantaj).reduce((s,p)=>s+p.leave+p.report,0);const docsAll=state.hrDocs.filter(d=>d.category!=='Bordro / ödeme belgesi');const docPct=Math.round(docsAll.filter(d=>['Mevcut','İmzalandı'].includes(d.status)).length/docsAll.length*100);const consistency=[['Çalışan kartı olmayan belge',state.hrDocs.filter(d=>!emp(d.employee_id)).length],['İçeriği olmayan (checksum’sız) belge',state.hrDocs.filter(d=>!d.sha256_checksum).length],['Mükerrer çalışan kartı',state.employees.length-new Set(state.employees.map(e=>e.name)).size],['Boş / mantıksız tarih',state.employees.filter(e=>!e.start||(e.end&&e.end<e.start)).length],['Kaynak kimliği eksik (kolayik kaydı)',state.hrDocs.filter(d=>d.source_system==='kolayik'&&!d.source_record_id).length],['Süresi dolmuş belge',state.hrDocs.filter(d=>d.status==='Süresi doldu').length]];return `<div class="toolbar"><span class="small muted">Veri güncelliği: ${new Date().toLocaleString('tr-TR')} · kaynak: JS People + Kolay İK import</span>${btn('CSV dışa aktar','hr-report-csv','sm','download')}</div><section class="metrics">${metric('Headcount',avg,`${teams.length} ekip`,'people')}${metric('Devir hızı (2026)',`%${turnover}`,`${exits} ayrılış / ${avg} ortalama`,'activity')}${metric('Devamsızlık (Ekim)',`${absence} <small>gün</small>`,'izin + rapor','clock')}${metric('Belge tamamlanma',`%${docPct}`,`${docsAll.length} belge`,'files')}${metric('Süresi dolacak',expiring(60).length,'60 gün','flag')}${metric('Arşiv tutarlılığı',consistency.reduce((s,c)=>s+c[1],0)?badge('Uyarı','warn'):badge('Temiz','success'),'kontrol listesi','shield')}</section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Ekip bazlı çalışan sayısı</h2></div><div class="panel-body">${svgBars(hc,{label:'Headcount'})}</div></div><div class="panel"><div class="panel-header"><h2>Arşiv tutarlılık raporu</h2></div><div class="panel-body">${tbl(['KONTROL','SAYI'],consistency.map(c=>`<tr><td>${esc(c[0])}</td><td>${c[1]?badge(c[1],'danger'):badge('0','success')}</td></tr>`).join(''),'Tutarlılık')}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>İK maliyeti → JS Finance</h2>${badge('Anonim toplulaştırma','neutral')}</div><div class="panel-body"><p>İK maliyetleri Finance kaynak planlamasıyla yalnızca ekip/maliyet merkezi düzeyinde ve anonimleştirilmiş toplamlarla eşleştirilir; bireysel ücret ifşası önlenir (k-anonimlik eşiği: ≥3 kişi). Devir hızı ve işe alım analizi JS Hire ile aynı gizlilik eşiğiyle birleştirilir.</p>${tbl(['MALİYET MERKEZİ','KİŞİ','TOPLAM (ANONİM)'],teams.map(t=>{const n=activeEmps().filter(e=>e.team===t).length;return `<tr><td>${esc(t)}</td><td>${n}</td><td class="mono">${n>=3?'•••• (toplam, Finance’e aktarılır)':'— (eşik altı, gösterilmez)'}</td></tr>`}).join(''),'Maliyet toplulaştırma')}</div></section>`}
function peopleMigration(){const m=state.migration;const done=m.phases.flatMap(p=>p[2]).filter(x=>x[1]).length,total=m.phases.flatMap(p=>p[2]).length;return `<div class="banner warn-banner">${ic('info')}<span><strong>Belirsizlik ve sınır:</strong> Kolay İK’nın herkese açık API referansı, bütün özlük belgelerinin, tüm geçmiş sürümlerin veya geçmiş silme/audit loglarının topluca indirilebildiğini garanti etmez. Bunlar için hesap içi ihracat fonksiyonları veya sağlayıcıdan veri paketi talebi değerlendirilecek; erişilemeyen kayıtlar “tam taşındı” olarak işaretlenmeyecek.</span></div><section class="metrics">${metric('Kontrol listesi',`${done}/${total}`,'Aşama A–D','check')}${metric('Batch',m.batches.length,`${m.batches.filter(b=>b.validation_status==='Doğrulandı').length} doğrulandı`,'refresh')}${metric('Kaynak kayıt',m.batches.reduce((s,b)=>s+b.records,0),'source_system=kolayik','connect')}${metric('Kabul kriteri',`${m.acceptance.filter(a=>a[1]).length}/${m.acceptance.length}`,'imzalanmadı','shield')}</section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Aşama A–D kontrol listesi</h2></div><div class="panel-body">${m.phases.map(([k,name,items],pi)=>`<h3 style="margin:10px 0 6px">Aşama ${k} — ${esc(name)}</h3><ul class="check-list">${items.map((it,i)=>`<li><button class="check ${it[1]?'done':''}" data-action="mig-toggle" data-id="${pi}:${i}" aria-pressed="${it[1]}" aria-label="${esc(it[0])}">${it[1]?ic('check'):''}</button><span>${esc(it[0])}</span></li>`).join('')}</ul>`).join('')}</div></div><div class="panel"><div class="panel-header"><h2>Kaynak otoritesi (alan bazlı)</h2>${badge('Çift yönlü eşitleme kapalı','warn')}</div><div class="panel-body">${Object.entries(m.authority).map(([k,v])=>`<label class="form-field" style="margin-bottom:8px">${esc(k)}<select data-authority="${esc(k)}">${['Kolay İK','JS People'].map(o=>option(o,o,v)).join('')}</select></label>`).join('')}<p class="small muted">Kaynak otoritesi işlem ve tarih bazlı belirlenmeden çift yönlü senkronizasyon başlatılmaz.</p><h3 style="margin:16px 0 6px">Kabul kriterleri</h3><ul class="check-list">${m.acceptance.map((a,i)=>`<li><button class="check ${a[1]?'done':''}" data-action="acc-toggle" data-id="${i}" aria-pressed="${a[1]}" aria-label="${esc(a[0])}">${a[1]?ic('check'):''}</button><span>${esc(a[0])}</span></li>`).join('')}</ul>${btn('Aktarım raporunu İK onayına gönder','mig-report','sm primary','approvals')}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Migration batch’leri</h2>${btn('Batch çalıştır (Timelog API)','mig-run','sm','refresh')}</div><div class="panel-body">${tbl(['BATCH ID','KAYNAK','KAYIT','source_system','validation_status','imported_at','mapped_by',''],m.batches.map(b=>`<tr><td class="mono">${b.id}</td><td>${esc(b.source)}</td><td>${b.records}</td><td class="mono">${b.source_system}</td><td>${badge(b.validation_status,b.validation_status==='Doğrulandı'?'success':b.validation_status.startsWith('Uyarı')?'danger':'warn')}</td><td class="mono">${b.imported_at||'—'}</td><td>${b.mapped_by?esc(empName(b.mapped_by)):'—'}</td><td>${b.validation_status.startsWith('Uyarı')||b.validation_status==='Bekliyor'?btn('Doğrula','mig-validate','sm','check',`data-id="${b.id}"`):''}</td></tr>`).join(''),'Batch')}</div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>external_source_map (örnek)</h2></div><div class="panel-body">${tbl(['source_type','source_id','target_id','target_table','batch'],m.sourceMap.map(r=>`<tr>${r.map(c=>`<td class="mono">${esc(c)}</td>`).join('')}</tr>`).join(''),'Kaynak eşleme')}</div></section>`}

/* ---------- My People (self-servis) ---------- */
function myPeopleSection(){const id=selfId();const e=emp(id);if(!e)return `<section class="panel settings-section"><h2>My People · self-servis</h2><p>Bu demo hesabı için çalışan kartı yok (kurucu / müşteri). Self-servis örneği için Creative, HR veya Payroll rolüyle gir.</p><div class="link-grid"><a class="link-card" href="#people/genel">${ic('people')}<span>JS People</span></a></div></section>`;const ls=state.leaves.filter(l=>l.person===id);const docs=docsOf(id).filter(d=>d.category!=='Bordro / ödeme belgesi');const pay=docsOf(id).filter(d=>d.category==='Bordro / ödeme belgesi');const req=docs.filter(d=>d.status==='Yükleme talebi');const used=e.leaveUsed||0,tot=entitlement(e)+(e.leaveOpening||0);return `<section class="panel settings-section" id="my-people"><div class="panel-header" style="padding:0 0 12px"><h2>My People · self-servis</h2>${badge('Yalnız kendi verin','neutral')}</div><section class="metrics">${metric('İzin hakkım',`${Math.max(0,tot-used)} <small>/ ${tot} gün</small>`,`${used} kullanıldı`,'clock')}${metric('Taleplerim',ls.filter(l=>l.status==='Bekliyor').length+state.expenseClaims.filter(x=>x.emp===id&&x.status==='Bekliyor').length,'izin + masraf bekleyen','activity')}${metric('Belgelerim',docs.length,req.length?`${req.length} yükleme talebi`:'tamamlanma %'+completion(id),'files')}${metric('Bordrolarım',pay.length,'yalnız sen görürsün','lock')}${metric('Zimmetlerim',state.hrAssets.filter(a=>a.emp===id&&a.status==='Zimmetli').length,'varlık','resources')}${metric('Eğitimlerim',state.trainingRecords.filter(t=>t.emp===id).length,`${state.trainingRecords.filter(t=>t.emp===id&&t.status==='Kayıtlı').length} açık`,'star')}</section>${req.length?`<div class="banner">${ic('upload')}<span>İK senden belge istiyor: ${req.map(d=>esc(d.subcategory)).join(', ')}.</span>${btn('Yükle','doc-upload-ss','sm primary','upload',`data-id="${req[0].id}"`)}</div>`:''}<div class="actions" style="margin-top:12px">${btn('İzin talebi','leave-new','','plus')}${btn('Masraf gir','exp-new','','plus')}${btn('Belge yükle','doc-upload','','upload',`data-id="${id}"`)}${btn('Çalışan 360 (kendi kartım)','e360-goto','','arrow',`data-id="${id}" data-tab="profil"`)}${btn('Bordrolarım','e360-goto','','lock',`data-id="${id}" data-tab="bordro"`)}</div><h3 style="margin-top:18px">Taleplerim</h3>${tbl(['TÜR','DETAY','ADIM','DURUM'],[...ls.map(l=>`<tr><td>İzin</td><td>${esc(l.type)} · ${date(l.from)}–${date(l.to)}</td><td>${l.status==='Bekliyor'?esc(l.step):'—'}</td><td>${badge(l.status)}</td></tr>`),...state.expenseClaims.filter(x=>x.emp===id).map(x=>`<tr><td>Masraf</td><td>${esc(x.category)} · ${money(x.amount*x.rate)}</td><td>${x.status==='Bekliyor'?esc(x.step):'—'}</td><td>${badge(x.status)}</td></tr>`)].join(''),'Taleplerim')}</section>`}
const _profileView=views.profile;views.profile=()=>_profileView()+(isClient()?'':myPeopleSection());

/* ---------- actions ---------- */
function pushDoc(e,cat,sub,o={}){const d={id:`D-${e.id}-${Date.now().toString(36)}`,organization_id:'org_jobs',employee_id:e.id,category:cat,subcategory:sub,original_filename:o.file||`${e.id}_${sub.replace(/[^a-zA-Z0-9]/g,'_').toLowerCase()}.pdf`,mime_type:'application/pdf',file_size:90000,storage_object_key:`hr/${e.id}/${sub.replace(/\W/g,'_')}.pdf`,sha256_checksum:fakeSha(e.id+sub+Date.now()),source_system:o.src||'upload',source_record_id:'',document_date:TODAY,effective_from:TODAY,expires_at:o.expires||'',retention_policy:o.ret||'İş akdi + 10 yıl',confidentiality_level:o.conf||'Standart',version_number:1,uploaded_by:account().person,import_batch_id:'',created_at:TODAY,deleted_at:'',legal_hold_flag:false,status:o.status||'Mevcut',versions:[],aiIndex:(o.conf||'Standart')==='Standart'};state.hrDocs.push(d);return d}
Object.assign(actions,{
ui(b){ui[b.dataset.key]=b.dataset.value;render()},
'e360-open'(b){if($('#modal').open)closeDialog();if(b.dataset.id==='BY'){location.hash='profile';return}ui.emp=b.dataset.id;ui.e360='profil';location.hash='people/c360';if(route==='people'&&sub==='c360')render()},
'e360-goto'(b){if($('#modal').open)closeDialog();ui.emp=b.dataset.id;ui.e360=b.dataset.tab||'profil';location.hash='people/c360';if(route==='people'&&sub==='c360')render()},
'arc-open'(b){ui.emp=b.dataset.id;ui.e360='ozluk';location.hash='people/c360'},
'doc-open'(b){if($('#modal').open)closeDialog();docDialog(b.dataset.id)},
'doc-download'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;logAccess(d,'indirdi');log(`Belge indirildi (kontrollü, imzalı URL 5 dk): ${d.subcategory} · ${empName(d.employee_id)}`);download(d.original_filename.replace('.pdf','.txt'),`JS PEOPLE · DEMO BELGE\n${d.subcategory}\nÇalışan: ${empName(d.employee_id)}\nsha256: ${d.sha256_checksum}\nBu dosya kurgusaldır; içerik yoktur.`);toast('İndirme imzalı URL ile başladı; erişim kaydı yazıldı.')},
'doc-replace'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;d.versions.push({version_number:d.version_number,sha256_checksum:d.sha256_checksum,created_at:d.created_at,uploaded_by:d.uploaded_by});d.version_number++;d.sha256_checksum=fakeSha(d.id+d.version_number);d.created_at=TODAY;d.uploaded_by=account().person;d.source_system='upload';if(d.expires_at){const dt=new Date(TODAY+'T12:00:00');dt.setFullYear(dt.getFullYear()+1);d.expires_at=dt.toISOString().slice(0,10)}d.status='Mevcut';logAccess(d,`değiştirdi (v${d.version_number} yüklendi, önceki sürüm korundu)`);closeDialog();done(`${d.subcategory} v${d.version_number} yüklendi; önceki sürüm korunuyor.`,`Belge yeni sürüm: ${d.subcategory} v${d.version_number} · ${empName(d.employee_id)}`)},
'doc-request'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;d.status='Yükleme talebi';addNotification(`İK belge istiyor: ${d.subcategory} (My People → Belgelerim)`,'profile');emit('document.requested',`doc:${d.id}`);done('Self-servis yükleme talebi gönderildi.',`Belge yükleme talebi: ${d.subcategory} · ${empName(d.employee_id)}`)},
'doc-request-all'(){const ds=state.hrDocs.filter(d=>d.status==='Eksik');ds.forEach(d=>d.status='Yükleme talebi');done(`${ds.length} belge için yükleme talebi gönderildi.`,`Toplu belge yükleme talebi: ${ds.length} belge`)},
'doc-upload-ss'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;d.status='HR onayı bekliyor';d.uploaded_by=d.employee_id;d.source_system='upload';d.sha256_checksum=fakeSha(d.id+'ss');addNotification(`${empName(d.employee_id)} belge yükledi: ${d.subcategory} · HR onayı bekliyor`,'people/arsiv-eksik');done('Belge yüklendi (self-servis); HR onayına düştü.',`Self-servis belge yüklendi: ${d.subcategory} · ${empName(d.employee_id)}`)},
'doc-approve'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;d.status='Mevcut';logAccess(d,'değiştirdi (HR onayı)');done('Belge onaylandı; arşive işlendi.',`Belge HR onayı: ${d.subcategory} · ${empName(d.employee_id)}`)},
'doc-reject'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;d.status='Reddedildi';done('Belge reddedildi; yeniden talep edilebilir.',`Belge reddedildi: ${d.subcategory} · ${empName(d.employee_id)}`)},
'doc-remind'(){const ds=expiring(60);ds.forEach(d=>addNotification(`Belge yenileme: ${empName(d.employee_id)} · ${d.subcategory} (${date(d.expires_at)})`,'people/arsiv-eksik'));done(`${ds.length} hatırlatma üretildi.`,`Belge yenileme hatırlatması: ${ds.length} belge`)},
'doc-hold'(b){const ds=docsOf(b.dataset.id);const on=!ds.some(d=>d.legal_hold_flag);ds.forEach(d=>d.legal_hold_flag=on);done(on?'Legal hold uygulandı; imha engellendi.':'Legal hold kaldırıldı.',`Legal hold ${on?'uygulandı':'kaldırıldı'}: ${empName(b.dataset.id)} (${ds.length} belge)`)},
'doc-hold-one'(b){const d=state.hrDocs.find(x=>x.id===b.dataset.id);if(!d)return;d.legal_hold_flag=!d.legal_hold_flag;closeDialog();done(d.legal_hold_flag?'Legal hold uygulandı.':'Legal hold kaldırıldı.',`Legal hold ${d.legal_hold_flag?'uygulandı':'kaldırıldı'}: ${d.subcategory} · ${empName(d.employee_id)}`)},
'doc-upload'(b){const e=emp(b.dataset.id);if(!e)return;openDialog('Belge yükle',`<form class="dialog-body" id="doc-upload-form" data-id="${e.id}"><p>${esc(e.name)} dosya dolabına belge ekle. Yükleme checksum ile kaydedilir; hassas sınıf AI indeksine girmez.</p><div class="form-grid"><label class="form-field">Kategori<select name="cat">${['İşe giriş evrakı','Sözleşme & ek protokol','İmzalı formlar','Görev tanımı','Eğitim belgeleri','Zimmet tutanağı','İzin evrakı','Ayrılış dosyası'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="form-field">Belge adı<input name="sub" required placeholder="Örn. Diploma" value="Diploma"></label><label class="form-field">Gizlilik sınıfı<select name="conf"><option>Standart</option><option>Gizli</option><option>Özel nitelikli</option></select></label><label class="form-field">Son geçerlilik<input type="date" name="expires"></label><label class="form-field full">Dosya<input type="file" name="file"></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">${canArchive()?'Arşive ekle':'HR onayına gönder'} ${ic('upload')}</button></div></form>`)},
'doctype-add'(){state.retentionPolicies.push(['Yeni belge türü','İş akdi + 10 yıl','Arşivle']);done('Belge türü eklendi (saklama politikasıyla).','Belge türü eklendi: Yeni belge türü')},
'arc-csv'(){csv('personel-arsiv-metadata.csv',[['document_id','employee','category','subcategory','status','source_system','document_date','expires_at','confidentiality','version','sha256'],...state.hrDocs.filter(d=>d.confidentiality_level!=='Bordro'&&d.confidentiality_level!=='Özel nitelikli').map(d=>[d.id,empName(d.employee_id),d.category,d.subcategory,d.status,d.source_system,d.document_date,d.expires_at,d.confidentiality_level,d.version_number,d.sha256_checksum])]);log('Arşiv metadata CSV dışa aktarıldı (bordro ve özel nitelikli hariç).');toast('Arşiv metadata indiriliyor.')},
'emp-csv'(){csv('personel-listesi.csv',[['id','name','title','team','company','manager','workType','start','end','status','externalId'],...state.employees.map(e=>[e.id,e.name,e.title,e.team,e.company,empName(e.manager),e.workType,e.start,e.end,e.status,e.externalId])]);log('Personel listesi CSV dışa aktarıldı.');toast('Personel listesi indiriliyor.')},
'arc-json'(){download('personel-arsiv-paketi.json',JSON.stringify({exported_at:new Date().toISOString(),by:account().email,employees:state.employees.map(({phone,address,tc,iban,emergency,...e})=>e),documents:state.hrDocs.filter(d=>!['Bordro','Özel nitelikli'].includes(d.confidentiality_level))},null,2),'application/json');log('Arşiv paketi (JSON) dışa aktarıldı; hassas sınıflar hariç.');toast('Arşiv paketi indiriliyor.')},
'access-csv'(){csv('belge-erisim-kayitlari.csv',[['at','who','role','doc','employee','action'],...state.accessLog.map(a=>[a.at,a.who,a.role,a.doc,empName(a.emp),a.action])]);toast('Erişim kayıtları indiriliyor.')},
'hr-import-sim'(){const id='MB-2026-'+String(state.migration.batches.length+1).padStart(2,'0');const n=7;state.employees.filter(e=>e.externalId).slice(0,n).forEach(e=>pushDoc(e,'İzin evrakı','Kolay İK izin kaydı (2025)',{src:'kolayik',ret:'5 yıl'}));state.hrDocs.slice(-n).forEach(d=>{d.import_batch_id=id;d.source_record_id='kik_doc_'+Math.floor(5000+Math.random()*900)});state.migration.batches.push({id,source:'CSV paketi · izin evrakı',records:n,source_system:'kolayik',validation_status:'Doğrulandı',imported_at:new Date().toLocaleString('tr-TR'),mapped_by:account().person});emit('hr.import.completed',`batch:${id}`);done(`${n} kayıt içe aktarıldı (batch ${id}); tekrar çalıştırma idempotent.`,`Toplu içe aktarım: ${id} · ${n} kayıt · source_system=kolayik`)},
'disposal-request'(b){const q=state.disposalQueue.find(x=>x.id===b.dataset.id);if(!q)return;if(q.hold){toast('Legal hold altında; imha edilemez.');return}q.status='Onay bekliyor (Onay Merkezi)';const a=requestApproval({name:`Belge imhası: ${q.doc} (${empName(q.emp)})`,kind:'Yetki değişikliği',desc:`Saklama süresi doldu (${q.policy}). İmha değiştirilemez kayıt bırakır.`});q.approval=a.id;done('İmha onayı Onay Merkezi’ne gönderildi.',`İmha onayı istendi: ${q.doc}`)},
'disposal-execute'(b){const q=state.disposalQueue.find(x=>x.id===b.dataset.id);if(!q)return;q.status='İmha edildi';state.accessLog.unshift({at:new Date().toLocaleString('tr-TR'),who:account().name,role:roleLabel[role()],doc:'—',emp:q.emp,action:`değiştirdi (imha: ${q.doc}, politika ${q.policy})`});done('Belge imha edildi; değiştirilemez kayıt yazıldı.',`Belge imha edildi: ${q.doc} · ${empName(q.emp)}`)},
'leave-step'(b){const l=state.leaves.find(x=>x.id===b.dataset.id);if(!l)return;const sel=document.querySelector(`[data-leave-deputy="${state.leaves.indexOf(l)}"]`);if(sel&&sel.value)l.deputy=sel.value;if(l.step==='Yönetici'){l.step='İK';done('Yönetici onayı verildi; İK onayı bekleniyor.',`İzin yönetici onayı: ${empName(l.person)} ${l.from}–${l.to}`);return}l.step='Tamamlandı';l.status='Onaylandı';const c=applyLeave(l);const ap=state.approvals.find(a=>a.kind==='İzin'&&a.leave===l.id&&a.status==='Bekliyor');if(ap){ap.status='Onaylandı';ap.decidedAt=now()}done(`İzin onaylandı. Kapasite düşüldü${c.length?`; ${c.length} görev çakışıyor → vekil ${empName(l.deputy)}`:''}.`,`İzin İK onayı: ${empName(l.person)} ${l.from}–${l.to}${c.length?' · '+c.length+' görev çakışması, vekil '+empName(l.deputy):''}`)},
'leave-reject'(b){const l=state.leaves.find(x=>x.id===b.dataset.id);if(!l)return;l.status='Reddedildi';l.step='—';done('İzin reddedildi.',`İzin reddedildi: ${empName(l.person)} ${l.from}–${l.to}`)},
'leave-cancel'(b){const l=state.leaves.find(x=>x.id===b.dataset.id);if(!l)return;l.status='İptal edildi';done('Talep iptal edildi.',`İzin talebi iptal: ${empName(l.person)}`)},
'puantaj-fix'(b){const p=state.puantaj[b.dataset.id];if(!p)return;p.missing=0;p.note='Düzeltme: '+now();done('Eksik süre düzeltildi (not + zaman damgası).',`Puantaj düzeltme: ${empName(b.dataset.id)}`)},
'puantaj-approve'(b){const p=state.puantaj[b.dataset.id];if(!p)return;p.status='İK onaylı';done('Puantaj İK onayı verildi.',`Puantaj İK onayı: ${empName(b.dataset.id)} · Ekim 2026`)},
'puantaj-send'(){if(!Object.values(state.puantaj).every(p=>p.status!=='Açık')){toast('Önce tüm satırlar İK onaylı olmalı.');return}emit('payroll.input.sent','payroll:2026-10');done('Puantaj bordro/finans entegrasyonuna gönderildi (Kolay İK/Paraşüt adaptörü · simülasyon).','Puantaj bordroya gönderildi: Ekim 2026',false)},
'ot-new'(b){openDialog('Fazla mesai talebi',`<form class="dialog-body" id="ot-form"><div class="form-grid"><label class="form-field">Kişi<select name="emp">${activeEmps().map(e=>option(e.id,e.name,b.dataset.id||selfId())).join('')}</select></label><label class="form-field">Tarih<input type="date" name="date" value="${TODAY}" required></label><label class="form-field">Saat<input type="number" name="hours" min="1" max="8" value="2" required></label><label class="form-field">Kanıt / ek<input name="evidence" placeholder="Çağrı kâğıdı, e-posta…"></label><label class="form-field full">Gerekçe<input name="reason" required></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Talep et ${ic('check')}</button></div></form>`)},
'ot-approve'(b){const o=state.overtime.find(x=>x.id===b.dataset.id);if(!o)return;o.status='Onaylandı';if(state.puantaj[o.emp])state.puantaj[o.emp].overtime+=o.hours;done('Fazla mesai onaylandı; puantaja işlendi.',`Fazla mesai onayı: ${empName(o.emp)} ${o.hours} saat`)},
'ot-reject'(b){const o=state.overtime.find(x=>x.id===b.dataset.id);if(!o)return;o.status='Reddedildi';done('Talep reddedildi.',`Fazla mesai reddedildi: ${empName(o.emp)}`)},
'shift-add'(){state.shifts.push({id:uid('sh'),name:'Yeni şablon',hours:'10:00–19:00',brk:60,days:'Pzt–Cum',location:'Ofis'});done('Vardiya şablonu eklendi.','Vardiya şablonu eklendi')},
'exp-new'(){if($('#modal').open)closeDialog();expDialog()},
'exp-step'(b){const x=state.expenseClaims.find(c=>c.id===b.dataset.id);if(!x)return;if(x.step==='Yönetici'){x.step='Finans';done('Yönetici onayı verildi; Finans onayı bekleniyor.',`Masraf yönetici onayı: ${empName(x.emp)} · ${money(x.amount*x.rate)}`);return}if(x.step==='Finans'){x.step='Ödeme';x.status='Onaylandı';if(!x.financeExpenseId){const id='x-'+x.id;state.expenses.unshift({id,desc:`Masraf · ${x.category} · ${x.note} (${empName(x.emp)})`,project:x.project||'',supplier:'Çalışan masrafı',amount:Math.round(x.amount*x.rate),status:'Onaylandı',category:'Masraf',date:x.date,source:'people:'+x.id});x.financeExpenseId=id}emit('expense.approved',`expense:${x.id}`);done('Finans onayı: JS Finance’te gider kaydı oluşturuldu (tek kayıt).',`Masraf Finans onayı: ${empName(x.emp)} · ${money(x.amount*x.rate)} → Finance ${x.financeExpenseId}`);return}x.status='Ödendi';x.step='Tamamlandı';done('Masraf ödendi işaretlendi.',`Masraf ödendi: ${empName(x.emp)} · ${money(x.amount*x.rate)}`)},
'exp-reject'(b){const x=state.expenseClaims.find(c=>c.id===b.dataset.id);if(!x)return;x.status='Reddedildi';x.step='—';done('Masraf reddedildi.',`Masraf reddedildi: ${empName(x.emp)}`)},
'adv-new'(){state.advances.unshift({id:uid('ad'),emp:selfId()==='BY'?'HO':selfId(),amount:3000,date:TODAY,remaining:3000,status:'Açık',note:'Yeni avans talebi'});done('Avans talebi oluşturuldu (onay: Finans).','Avans talebi oluşturuldu: 3.000 TL')},
'adv-settle'(b){const a=state.advances.find(x=>x.id===b.dataset.id);if(!a)return;const paid=state.expenseClaims.filter(x=>x.emp===a.emp&&['Onaylandı','Ödendi'].includes(x.status)).reduce((s,x)=>s+x.amount*x.rate,0);const off=Math.min(a.remaining,paid||a.remaining);a.remaining=Math.max(0,a.remaining-off);if(!a.remaining)a.status='Mahsup edildi';done(`${money(off)} mahsup edildi; kalan ${money(a.remaining)}.`,`Avans mahsup: ${empName(a.emp)} · ${money(off)}`)},
'asset-return'(b){const a=state.hrAssets.find(x=>x.id===b.dataset.id);if(!a)return;const e=emp(a.emp);a.status='İade edildi';a.returned=TODAY;if(e)pushDoc(e,'Zimmet tutanağı',`Zimmet iade tutanağı · ${a.name}`,{ret:'İade + 2 yıl'});const eq=state.equipment?.find(q=>q.name===a.name);if(eq){eq.assigned='';eq.status='Depoda'}done('İade alındı; iade tutanağı arşive eklendi.',`Zimmet iadesi: ${a.name} · ${empName(a.emp)}`)},
'asset-damage'(b){const a=state.hrAssets.find(x=>x.id===b.dataset.id);if(!a)return;a.damage.push({at:TODAY,text:'Hasar bildirimi (fotoğraf eklendi)'});a.condition='Hasarlı · inceleme';done('Hasar kaydı eklendi.',`Zimmet hasar kaydı: ${a.name}`)},
'asset-assign'(b){const a=b.dataset.asset?state.hrAssets.find(x=>x.id===b.dataset.asset):state.hrAssets.find(x=>x.status==='Depoda');const e=emp(b.dataset.id)||curEmp();if(!a||!e){toast('Depoda boş varlık yok.');return}a.emp=e.id;a.status='Zimmetli';a.delivered=TODAY;a.returned='';pushDoc(e,'Zimmet tutanağı',`Zimmet teslim tutanağı · ${a.name}`,{ret:'İade + 2 yıl',status:'İmza bekliyor'});done(`${a.name} → ${e.name} zimmetlendi; tutanak imzaya gönderildi.`,`Zimmet atandı: ${a.name} → ${e.name}`)},
'asset-new'(){state.hrAssets.push({id:uid('as'),name:'Yeni varlık',type:'Aksesuar',serial:'SN-'+Date.now().toString(36).toUpperCase(),emp:'',delivered:'',returned:'',condition:'İyi',status:'Depoda',damage:[]});done('Varlık eklendi (depoda).','Varlık eklendi')},
'asset-csv'(){csv('zimmet.csv',[['id','name','type','serial','employee','delivered','returned','status','condition'],...state.hrAssets.map(a=>[a.id,a.name,a.type,a.serial,empName(a.emp),a.delivered,a.returned,a.status,a.condition])]);toast('Zimmet listesi indiriliyor.')},
'tr-add'(){state.trainings.push({id:uid('tr'),name:'Yeni eğitim',mandatory:false,hours:2,renew:'—'});done('Eğitim eklendi.','Eğitim kataloğuna eklendi')},
'tr-complete'(b){const r=state.trainingRecords.find(x=>x.id===b.dataset.id);if(!r)return;const t=state.trainings.find(x=>x.id===r.training);r.status='Tamamlandı';r.completed=TODAY;r.cert=t?.name+' sertifikası';const dt=new Date(TODAY+'T12:00:00');dt.setFullYear(dt.getFullYear()+(t?.renew?.includes('3')?3:t?.renew?.includes('2')?2:1));r.expires=dt.toISOString().slice(0,10);const e=emp(r.emp);if(e)pushDoc(e,'Eğitim belgeleri',r.cert,{ret:'3 yıl',expires:r.expires});done('Eğitim tamamlandı; sertifika arşive eklendi.',`Eğitim tamamlandı: ${empName(r.emp)} · ${t?.name}`)},
'cert-renew'(b){const r=state.trainingRecords.find(x=>x.id===b.dataset.id);if(!r)return;const dt=new Date(TODAY+'T12:00:00');dt.setFullYear(dt.getFullYear()+2);r.expires=dt.toISOString().slice(0,10);r.completed=TODAY;const d=state.hrDocs.find(x=>x.employee_id===r.emp&&x.subcategory===r.cert);if(d){d.versions.push({version_number:d.version_number,sha256_checksum:d.sha256_checksum,created_at:d.created_at});d.version_number++;d.expires_at=r.expires;d.status='Mevcut';d.sha256_checksum=fakeSha(d.id+d.version_number)}done('Sertifika yenilendi; önceki sürüm korundu.',`Sertifika yenilendi: ${empName(r.emp)} · ${r.cert}`)},
'perf-advance'(){const c=state.perfCycle;const i=c.steps.indexOf(c.stage);if(i<c.steps.length-1){c.stage=c.steps[i+1];state.perfReviews.forEach(r=>r.status=c.stage)}done(`Döngü aşaması: ${c.stage}.`,`Performans döngüsü aşaması: ${c.stage}`)},
'perf-add'(b){state.perfReviews.push({emp:b.dataset.id,self:'',manager:'',goals:[['Yeni hedef',0]],status:state.perfCycle.stage});done('Döngüye eklendi.',`Performans döngüsüne eklendi: ${empName(b.dataset.id)}`)},
'goal-add'(b){const r=state.perfReviews[Number(b.dataset.id)];if(!r)return;r.goals.push(['Yeni hedef',0]);done('Hedef eklendi.',`Hedef eklendi: ${empName(r.emp)}`)},
'comp-new'(){state.compReviews.push({id:uid('cr'),emp:'SK',type:'Ücret revizyonu',proposal:'+%10 (piyasa düzeltmesi)',effective:'2027-01-01',status:'Taslak',step:'Yönetici',by:account().person,amount:MASK});done('Öneri taslağı oluşturuldu.','Ücret değerlendirme önerisi taslağı: Seda Karabacak')},
'comp-submit'(b){const c=state.compReviews.find(x=>x.id===b.dataset.id);if(!c)return;c.status='Onay bekliyor';c.step='Owner';const a=requestApproval({name:`Ücret değerlendirmesi: ${empName(c.emp)} (${c.type})`,kind:'Yetki değişikliği',desc:'Tutar onay bildiriminde gösterilmez; ayrı ücret yetkisi + step-up MFA ile görülür.',comp:c.id});c.approval=a.id;done('Onaya gönderildi (tutar maskeli).',`Ücret önerisi onaya gönderildi: ${empName(c.emp)}`)},
stepup(){if($('#modal').open)closeDialog();stepUpDialog()},
'payroll-publish'(b){const r=state.payrollRuns.find(x=>x.month===b.dataset.id);if(!r)return;r.status='Yayımlandı';state.hrDocs.filter(d=>d.category==='Bordro / ödeme belgesi'&&d.subcategory.endsWith(r.month)).forEach(d=>{addNotification(`Bordron hazır: ${r.month} (My People → Bordrolarım)`,'profile')});emit('payroll.published',`payroll:${r.month}`);done(`${r.month} bordroları yayımlandı; ${r.docs} çalışana bildirim gitti.`,`Bordro yayımlandı: ${r.month} · ${r.docs} belge`)},
'payroll-import'(){const m='2026-10';if(!state.payrollRuns.some(r=>r.month===m)){activeEmps().filter(e=>e.workType!=='Freelance').forEach(e=>pushDoc(e,'Bordro / ödeme belgesi',`Bordro ${m}`,{conf:'Bordro',src:'kolayik'}));state.payrollRuns.push({month:m,status:'Hazır · yayımlanmadı',docs:activeEmps().filter(e=>e.workType!=='Freelance').length})}ui.payMonth=m;done('Ekim bordro PDF’leri içe aktarıldı (Kolay İK · simülasyon).','Bordro belgeleri içe aktarıldı: 2026-10')},
'emp-offboard'(b){const e=emp(b.dataset.id);if(!e)return;e.status='Ayrıldı';e.end=e.end||TODAY;(e.offboarding||[]).forEach(x=>x[1]=true);state.hrAssets.filter(a=>a.emp===e.id&&a.status==='Zimmetli').forEach(a=>{a.status='İade edildi';a.returned=TODAY});pushDoc(e,'Ayrılış dosyası','İbraname',{conf:'Gizli'});pushDoc(e,'Ayrılış dosyası','Çalışma belgesi');const u=state.users.find(x=>x.name===e.name);if(u){u.status='Askıda';u.sessions=0}state.tasks.filter(t=>!t.done&&t.owner===e.id).forEach(t=>{t.owner=e.manager!=='BY'?e.manager:'OE';t.labels=[...new Set([...(t.labels||[]),'yeniden atandı'])]});e.history=[...(e.history||[]),{at:TODAY,type:'Ayrılış',text:'Erişim kapatıldı; belgeler saklama politikasına göre arşivlendi'}];emit('employee.offboarded',`employee:${e.id}`);done(`${e.name} ayrılışı tamamlandı: erişim kapatıldı, zimmet iade, görevler yeniden atandı, dosya arşivlendi.`,`Offboarding tamamlandı: ${e.name}`)},
'hist-add'(b){const e=emp(b.dataset.id);if(!e)return;e.history=[...(e.history||[]),{at:TODAY,type:'Rol değişimi',text:'Kayıt eklendi (düzenle)'}];done('Geçmiş kaydı eklendi.',`Çalışma geçmişi kaydı: ${e.name}`)},
'ws-approve'(b){const w=state.wsRequests.find(x=>x.id===b.dataset.id);if(!w)return;w.status='Açıldı';const e=emp(w.emp);const it=e?.onboarding?.find(x=>x[0].includes('Hesap'));if(it)it[1]=true;done('Workspace kullanıcısı açıldı (simülasyon).',`Workspace kullanıcısı açıldı: ${w.email}`)},
'mig-toggle'(b){const [p,i]=b.dataset.id.split(':').map(Number);const it=state.migration.phases[p][2][i];it[1]=!it[1];done(null,`Kolay İK aktarım kontrol listesi: ${it[0].slice(0,60)}… → ${it[1]?'tamam':'açık'}`)},
'acc-toggle'(b){const it=state.migration.acceptance[Number(b.dataset.id)];it[1]=!it[1];done(null,`Aktarım kabul kriteri: ${it[0].slice(0,60)}… → ${it[1]?'sağlandı':'açık'}`)},
'mig-run'(){const b=state.migration.batches.find(x=>x.validation_status==='Bekliyor');if(!b){toast('Bekleyen batch yok.');return}b.imported_at=new Date().toLocaleString('tr-TR');b.mapped_by=account().person;b.validation_status='Uyarı · 12 kayıtta saat dilimi düzeltildi';emit('hr.import.completed',`batch:${b.id}`);done(`${b.id} çalıştı: ${b.records} kayıt; doğrulama uyarısı var.`,`Migration batch çalıştı: ${b.id}`)},
'mig-validate'(b){const x=state.migration.batches.find(y=>y.id===b.dataset.id);if(!x)return;x.validation_status='Doğrulandı';done('Batch doğrulandı (checksum + ID/tarih/tür/sahiplik).',`Migration batch doğrulandı: ${x.id}`)},
'mig-report'(){requestApproval({name:'Kolay İK aktarım raporu · İK onayı',kind:'Yetki değişikliği',desc:`${state.migration.batches.length} batch, ${state.migration.acceptance.filter(a=>a[1]).length}/${state.migration.acceptance.length} kabul kriteri. Değişiklik günlüğü ekli.`});done('Aktarım raporu Onay Merkezi’ne gönderildi.','Kolay İK aktarım raporu onaya gönderildi')},
'breakglass-request'(b){const key=b.dataset.id||'can.read.hr.archive';const a=requestApproval({name:`Break-glass erişim: ${key} (${account().name})`,kind:'Yetki değişikliği',desc:'Acil erişim politikası: 60 dakika süreli, gerekçeli, step-up MFA + audit. Onay owner dışı bir yetkiliden alınır.',breakGlass:key});state.securityEvents?.unshift({at:now(),type:'Break-glass',who:account().email,detail:`${key} için acil erişim talebi (${a.id})`,level:'warn'});done('Break-glass talebi Onay Merkezi’ne düştü; onaylanınca 60 dk geçerli.',`Break-glass talebi: ${key}`)}
});
Object.assign(forms,{
'stepup-form'(get){if(!/^\d{6}$/.test(get('code')))return;state.stepUp={until:Date.now()+600000,by:account().id};state.securityEvents?.unshift({at:now(),type:'Step-up MFA',who:account().email,detail:'Bordro/ücret veri sınıfı için ek doğrulama',level:'ok'});closeDialog();done('Doğrulandı · 10 dk.','Step-up MFA doğrulandı (bordro/ücret kapsamı)')},
'exp-form'(get){const x={id:uid('ec'),emp:get('emp'),category:get('category'),amount:Number(get('amount')),currency:get('currency'),rate:Number(get('rate'))||1,project:get('project'),costCenter:get('cc'),receipt:get('receipt'),note:get('note'),status:'Bekliyor',step:'Yönetici',date:TODAY,financeExpenseId:''};state.expenseClaims.unshift(x);emit('expense.submitted',`expense:${x.id}`);addNotification(`Masraf onayı: ${empName(x.emp)} · ${money(x.amount*x.rate)}`,'people/masraf');closeDialog();done('Masraf onaya gönderildi (Yönetici → Finans).',`Masraf talebi: ${empName(x.emp)} · ${x.category} · ${money(x.amount*x.rate)}`)},
'ot-form'(get){state.overtime.unshift({id:uid('ot'),emp:get('emp'),date:get('date'),hours:Number(get('hours')),reason:get('reason'),status:'Bekliyor',evidence:get('evidence')||'—'});closeDialog();done('Fazla mesai talebi oluşturuldu.',`Fazla mesai talebi: ${empName(get('emp'))} ${get('hours')} saat`)},
'doc-upload-form'(get,data,f){const e=emp(f.dataset.id);if(!e||!get('sub'))return;const d=pushDoc(e,get('cat'),get('sub'),{conf:get('conf'),expires:get('expires'),status:canArchive()?'Mevcut':'HR onayı bekliyor'});if(!canArchive())addNotification(`${e.name} belge yükledi: ${d.subcategory}`,'people/arsiv-eksik');closeDialog();done(canArchive()?'Belge arşive eklendi.':'Belge HR onayına gönderildi.',`Belge yüklendi: ${d.subcategory} · ${e.name} (${d.confidentiality_level})`)},
'perf-form'(get,data,f){const r=state.perfReviews[Number(f.dataset.id)];if(!r)return;r.self=get('self');r.manager=get('manager');if(r.manager)r.status='Yönetici geri bildirimi';else if(r.self)r.status='Öz değerlendirme';done('Değerlendirme kaydedildi.',`Performans değerlendirmesi kaydedildi: ${empName(r.emp)}`)}
});
/* leave-form override: multi-step + approval link */
forms['leave-form']=function(get){const from=get('from'),to=get('to');const days=Math.max(1,Math.round((new Date(to)-new Date(from))/86400000)+1);const l={id:uid('lv'),person:get('person'),from,to,type:get('type'),days,status:'Bekliyor',step:'Yönetici',deputy:'',requested:TODAY};state.leaves.push(l);const a=requestApproval({name:`${empName(l.person)} · ${l.type} ${date(from)}–${date(to)} (${days} gün)`,kind:'İzin',desc:'Çalışan talebi → birim yöneticisi → İK onayı. Onaylı izin kapasiteden düşer; çakışan görevler işaretlenir.',leave:l.id});l.approval=a.id;emit('leave.requested',`leave:${l.id}`);closeDialog();done('İzin talebi gönderildi: yönetici onayı bekleniyor.',`İzin talebi: ${empName(l.person)} ${l.type} ${from}–${to} (${days} gün)`)};
const _applyApproval=applyApproval;applyApproval=function(a){if(a.status==='Onaylandı'){if(a.kind==='İzin'){const l=state.leaves.find(x=>x.id===a.leave)||state.leaves.find(x=>x.status==='Bekliyor'&&a.name.includes(empName(x.person)));if(l&&l.status==='Bekliyor'){l.status='Onaylandı';l.step='Tamamlandı';const c=applyLeave(l);if(c.length)toast(`İzin onaylandı; ${c.length} görev çakışıyor, vekil: ${empName(l.deputy)}`)}return}if(a.comp){const c=state.compReviews.find(x=>x.id===a.comp);if(c){c.status='Onaylandı';c.step='—';const e=emp(c.emp);if(e)e.history=[...(e.history||[]),{at:TODAY,type:'Ücret revizyonu',text:MASK}]}}if(a.breakGlass){state.breakGlass[a.breakGlass]={until:Date.now()+3600000,by:a.by,approval:a.id};state.securityEvents?.unshift({at:now(),type:'Break-glass',who:account().email,detail:`${a.breakGlass} 60 dk açıldı (onay ${a.id})`,level:'warn'})}const q=state.disposalQueue.find(x=>x.approval===a.id);if(q)q.status='Onaylandı'}if(a.status==='Reddedildi'&&a.leave){const l=state.leaves.find(x=>x.id===a.leave);if(l){l.status='Reddedildi';l.step='—'}}_applyApproval(a)};
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.docStatus!==undefined){const d=state.hrDocs[Number(t.dataset.docStatus)];if(!d)return;const old=d.status;d.status=t.value;const k=SIGN_SET.find(s=>s[1]===d.subcategory)?.[0];const em=emp(d.employee_id);if(k&&em?.signatures)em.signatures[k]=t.value;logAccess(d,`değiştirdi (durum ${old} → ${t.value})`);done(`${d.subcategory}: ${t.value}`,`Belge durumu: ${d.subcategory} · ${empName(d.employee_id)} · ${old} → ${t.value}`,false);return}if(t.dataset.leaveDeputy!==undefined){const l=state.leaves[Number(t.dataset.leaveDeputy)];if(!l)return;l.deputy=t.value;done(t.value?`Vekil: ${empName(t.value)}`:'Vekil kaldırıldı.',`İzin vekili: ${empName(l.person)} → ${empName(t.value)||'—'}`,false);return}if(t.dataset.shift){state.shiftPlan[t.dataset.shift]=t.value;done('Vardiya planı güncellendi.',`Vardiya: ${empName(t.dataset.shift)} → ${state.shifts.find(s=>s.id===t.value)?.name}`);return}if(t.dataset.enroll!==undefined&&t.value){state.trainingRecords.push({id:uid('tz'),emp:t.dataset.enroll,training:t.value,status:'Kayıtlı',completed:'',expires:'',cert:''});done('Eğitime kaydedildi.',`Eğitim kaydı: ${empName(t.dataset.enroll)} · ${state.trainings.find(x=>x.id===t.value)?.name}`);return}if(t.dataset.perfAdd!==undefined&&t.value){state.perfReviews.push({emp:t.value,self:'',manager:'',goals:[['Yeni hedef',0]],status:state.perfCycle.stage});done('Döngüye eklendi.',`Performans döngüsüne eklendi: ${empName(t.value)}`);return}if(t.dataset.authority){state.migration.authority[t.dataset.authority]=t.value;done(`${t.dataset.authority}: kaynak otoritesi ${t.value}.`,`Kaynak otoritesi: ${t.dataset.authority} → ${t.value}`,false);return}if(t.dataset.goal){const [ri,gi]=t.dataset.goal.split(':').map(Number);const r=state.perfReviews[ri];if(!r)return;r.goals[gi][1]=Number(t.value);done(null,`Hedef ilerlemesi: ${empName(r.emp)} · ${r.goals[gi][0]} %${t.value}`,false);t.closest('.goal').querySelector('strong').textContent='%'+t.value;t.closest('.goal').querySelector('.progress span').style.width=t.value+'%';return}if(t.id==='hr-import-file'){const f=t.files?.[0];if(!f)return;const id='MB-2026-'+String(state.migration.batches.length+1).padStart(2,'0');state.migration.batches.push({id,source:`Dosya · ${f.name}`,records:Math.max(1,Math.round(f.size/180)),source_system:'kolayik',validation_status:'Bekliyor',imported_at:new Date().toLocaleString('tr-TR'),mapped_by:account().person});done(`${f.name} alındı; batch ${id} doğrulama bekliyor.`,`Dosya içe aktarımı: ${f.name} → ${id}`)}});

views.people=people;
